INSERT INTO `app_details` (`app_id`, `short_label`, `full_name`, `category_badge`, `app_url`, `target_audience`, `deploy_time`, `sso_scopes`, `preview_image`, `full_description`) VALUES ('mamnon', '👶 Mầm non AI', 'EduManager Pro — Quản lý Trường Mầm non & AI', '🏫 Khối Giáo dục K-12 (Mầm non)', 'https://mamnon.techcorp.info.vn', 'Trường Mầm non Công lập, Tư thục & Quốc tế', '15 phút (Có sẵn danh mục chuẩn Bộ GD&ĐT)', 'TechCorp ID • Sổ liên lạc • VietQR', 'https://images.unsplash.com/photo-1587654780291-39c9404d746b?auto=format&fit=crop&w=1200&q=80', 'Giải pháp quản lý toàn diện dành riêng cho các trường Mầm non hiện đại: Tự động hóa từ khâu tuyển sinh, điểm danh AI nhận diện khuôn mặt, tính khẩu phần dinh dưỡng chuẩn Viện Dinh dưỡng đến Sổ liên lạc điện tử đa phương tiện và gạch nợ học phí QR tự động.') ON DUPLICATE KEY UPDATE `short_label`=VALUES(`short_label`), `full_name`=VALUES(`full_name`), `category_badge`=VALUES(`category_badge`), `app_url`=VALUES(`app_url`), `target_audience`=VALUES(`target_audience`), `deploy_time`=VALUES(`deploy_time`), `sso_scopes`=VALUES(`sso_scopes`), `preview_image`=VALUES(`preview_image`), `full_description`=VALUES(`full_description`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('mamnon', 1, '📸', '1. Điểm danh AI & Đón trả Trẻ An toàn', 'Nhận diện khuôn mặt hoặc thẻ QR khi phụ huynh đưa/đón trẻ, tự động bắn thông báo kèm hình ảnh thời gian thực về ứng dụng Phụ huynh.', '[\"Cảnh báo người lạ đón hộ chưa đăng ký\",\"Thống kê sĩ số từng lớp theo giờ\",\"Tự động trừ tiền ăn khi trẻ nghỉ có phép\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('mamnon', 2, '🥗', '2. Quản lý Thực đơn Dinh dưỡng & Bếp ăn', 'Thiết lập thực đơn tuần/tháng, tự động cân đối tỷ lệ Đạm - Béo - Đường (Kcal) và tính định lượng nguyên vật liệu đi chợ hàng ngày.', '[\"Ngân hàng 500+ món ăn mầm non chuẩn\",\"Quản lý kho thực phẩm & lưu mẫu thức ăn\",\"Kết nối nhà cung cấp thực phẩm VietGAP trên Hub\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('mamnon', 3, '📱', '3. Sổ Liên lạc Điện tử & Album Ảnh Lớp học', 'Cầu nối tức thì giữa Giáo viên và Phụ huynh: Cập nhật nhật ký ăn - ngủ - vệ sinh, biểu đồ chiều cao cân nặng WHO và xin nghỉ phép 1 chạm.', '[\"Chia sẻ ảnh/video hoạt động hàng ngày\",\"Theo dõi biểu đồ tăng trưởng & tiêm chủng\",\"Tích hợp nhận E-Voucher học bổng từ Hệ sinh thái\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('mamnon', 4, '💳', '4. Thu Học phí Động & Gạch nợ VietQR', 'Tự động tổng hợp tiền học phí, tiền ăn, dịch vụ ngoại khóa và phát hành mã QR thanh toán định danh từng bé.', '[\"Gạch nợ tự động 100% trong 3 giây\",\"Nhắc phí lịch sự qua Zalo/App Phụ huynh\",\"Báo cáo công nợ & doanh thu thời gian thực\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('mamnon', 5, '👩‍🏫', '5. Quản lý Hồ sơ Giáo viên & Phân công Ca trực', 'Quản lý hồ sơ nhân sự, bằng cấp sư phạm mầm non, chấm công giáo viên/bảo mẫu và đánh giá KPI chăm sóc lớp.', '[\"Phân công giáo viên phụ trách lớp\",\"Tính lương, phụ cấp & thưởng tự động\",\"Kế hoạch bài giảng theo chủ đề năm học\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('mamnon', 6, '📊', '6. Dashboard Điều hành cho Chủ trường & Hiệu trưởng', 'Hệ thống báo cáo trực quan giúp Chủ trường nắm bắt toàn bộ tình hình tuyển sinh, tài chính, sĩ số và phản hồi phụ huynh mọi lúc mọi nơi.', '[\"Phễu CRM chăm sóc phụ huynh tham quan trường\",\"Dự báo doanh thu & chi phí vận hành\",\"Xuất báo cáo chuẩn Phòng/Sở GD&ĐT\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('mamnon', 1, '🎁 Liên thông Trung tâm Ngoại ngữ (ttnn)', 'Tự động gửi tặng học bổng & suất kiểm tra tiếng Anh thiếu nhi cho phụ huynh trên Sổ liên lạc điện tử.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('mamnon', 2, '🥬 Kết nối Doanh nghiệp Cung ứng (erp)', 'Đặt hàng suất ăn học đường, sữa và thiết bị giáo dục với chiết khấu nội bộ 12% - 25% từ các DN thành viên.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('mamnon', 3, '🤖 Tuyển Giáo viên Mầm non (jobai)', 'Đăng tin tuyển dụng giáo viên/bảo mẫu trực tiếp lên Sàn HireMind AI và trường Đại học/Cao đẳng Sư phạm.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_details` (`app_id`, `short_label`, `full_name`, `category_badge`, `app_url`, `target_audience`, `deploy_time`, `sso_scopes`, `preview_image`, `full_description`) VALUES ('tieuhoc', '📘 Tiểu học AI', 'EduManager Pro — Quản lý Trường Tiểu học & AI', '🏫 Khối Giáo dục K-12 (Tiểu học)', 'https://tieuhoc.techcorp.info.vn', 'Trường Tiểu học Công lập, Tư thục & Liên cấp', '15 phút (Chuẩn Thông tư 27 Bộ GD&ĐT)', 'TechCorp ID • Học bạ số • LMS', 'https://images.unsplash.com/photo-1503676260728-1c00da094a0b?auto=format&fit=crop&w=1200&q=80', 'Hệ thống quản trị trường Tiểu học thông minh tích hợp Trợ lý AI: Chuẩn hóa đánh giá phẩm chất và năng lực học sinh theo Thông tư 27/2020/TT-BGDĐT, ký số Học bạ điện tử, quản lý bán trú và kết nối Phụ huynh toàn diện.') ON DUPLICATE KEY UPDATE `short_label`=VALUES(`short_label`), `full_name`=VALUES(`full_name`), `category_badge`=VALUES(`category_badge`), `app_url`=VALUES(`app_url`), `target_audience`=VALUES(`target_audience`), `deploy_time`=VALUES(`deploy_time`), `sso_scopes`=VALUES(`sso_scopes`), `preview_image`=VALUES(`preview_image`), `full_description`=VALUES(`full_description`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('tieuhoc', 1, '📋', '1. Đánh giá Phẩm chất & Năng lực (Thông tư 27)', 'Hỗ trợ giáo viên nhận xét thường xuyên và định kỳ bằng ngân hàng câu nhận xét thông minh do AI gợi ý sát với năng lực từng học sinh.', '[\"Nhập điểm & mức đạt (T, H, C) siêu tốc\",\"Gợi ý nhận xét cá nhân hóa bằng AI\",\"Tổng hợp bảng tổng hợp kết quả đánh giá cuối kỳ\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('tieuhoc', 2, '🔏', '2. Học bạ Số & Sổ Đăng bộ Điện tử', 'Số hóa 100% hồ sơ học vụ, khởi tạo và ký số Học bạ điện tử chuẩn cấu trúc dữ liệu ngành Giáo dục.', '[\"Ký số tập trung cho Giáo viên & Hiệu trưởng\",\"Tra cứu & chuyển trường trực tuyến\",\"Lưu trữ an toàn trên hạ tầng Cloud\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('tieuhoc', 3, '🍱', '3. Quản lý Bán trú, Xe đưa đón & Ngoại khóa', 'Quản lý điểm danh ăn trưa bán trú, theo dõi lộ trình xe buýt học đường (School Bus) và đăng ký câu lạc bộ kỹ năng sau giờ học.', '[\"Điểm danh lên/xuống xe buýt thông báo Phụ huynh\",\"Quản lý thực đơn bán trú tiểu học\",\"Đăng ký CLB Tiếng Anh, STEM, Bơi lội\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('tieuhoc', 4, '👨‍👩‍👧', '4. Cổng Phụ huynh & Sổ Liên lạc Thông minh', 'Phụ huynh theo dõi thời khóa biểu, bài tập ôn luyện ở nhà, kết quả rèn luyện và trao đổi trực tiếp với Giáo viên chủ nhiệm.', '[\"Thông báo lịch thi & sự kiện nhà trường\",\"Thanh toán học phí & bán trú qua VietQR\",\"Nhận ưu đãi khóa học hè từ Hệ sinh thái\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('tieuhoc', 5, '🧠', '5. Trợ lý AI Soạn Giáo án & Đề kiểm tra', 'Tích hợp công cụ AI giúp giáo viên Tiểu học thiết kế kế hoạch bài dạy Chương trình GDPT 2018 và tạo phiếu bài tập tương tác.', '[\"Tạo phiếu bài tập Toán - Tiếng Việt - Tiếng Anh\",\"Liên thông sang TechCorp LMS để giao bài\",\"Thống kê tỷ lệ hoàn thành bài tập của lớp\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('tieuhoc', 6, '🏛️', '6. Quản trị Giáo vụ, Thư viện & Thiết bị Dạy học', 'Xếp thời khóa biểu tự động, quản lý mượn trả sách thư viện trường học và theo dõi danh mục thiết bị dạy học tối thiểu.', '[\"Xếp thời khóa biểu 2 buổi/ngày tự động\",\"Quản lý mã vạch sách thư viện\",\"Báo cáo thống kê EMIS định kỳ\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('tieuhoc', 1, '📝 Liên thông Đấu trường Thi Online (lms)', 'Học sinh Tiểu học tham gia các kỳ thi Olympic Toán, Tiếng Anh thiếu nhi trực tuyến với tài khoản SSO.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('tieuhoc', 2, '📘 Chuyển tiếp Hồ sơ lên THCS (thcs)', 'Đồng bộ 1-Click toàn bộ học bạ số và lịch sử phát triển năng lực khi học sinh chuyển cấp lên lớp 6.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('tieuhoc', 3, '🏫 Kết nối Trung tâm Anh ngữ & Kỹ năng (ttnn)', 'Phối hợp tổ chức câu lạc bộ Tiếng Anh với giáo viên bản xứ ngay tại trường Tiểu học.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_details` (`app_id`, `short_label`, `full_name`, `category_badge`, `app_url`, `target_audience`, `deploy_time`, `sso_scopes`, `preview_image`, `full_description`) VALUES ('thcs', '📙 Trường THCS', 'EduManager Pro — Quản lý Trường THCS & Trợ lý AI', '🏫 Khối Giáo dục K-12 (Trung học Cơ sở)', 'https://thcs.techcorp.info.vn', 'Trường Trung học Cơ sở & Trường Phổ thông Liên cấp', '15 phút (Chuẩn Thông tư 22 Bộ GD&ĐT)', 'TechCorp ID • Sổ điểm Số • LMS', 'https://images.unsplash.com/photo-1509062522246-3755977927d7?auto=format&fit=crop&w=1200&q=80', 'Giải pháp quản trị giáo vụ Trung học Cơ sở toàn diện: Xếp thời khóa biểu AI, quản lý Sổ gọi tên và ghi điểm điện tử theo Thông tư 22, Học bạ số, kiểm tra định kỳ chống gian lận và định hướng phân luồng sau THCS.') ON DUPLICATE KEY UPDATE `short_label`=VALUES(`short_label`), `full_name`=VALUES(`full_name`), `category_badge`=VALUES(`category_badge`), `app_url`=VALUES(`app_url`), `target_audience`=VALUES(`target_audience`), `deploy_time`=VALUES(`deploy_time`), `sso_scopes`=VALUES(`sso_scopes`), `preview_image`=VALUES(`preview_image`), `full_description`=VALUES(`full_description`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('thcs', 1, '📊', '1. Sổ Điểm Điện tử & Đánh giá theo Thông tư 22', 'Tự động tính điểm trung bình môn, xếp loại kết quả học tập và rèn luyện học kỳ/cả năm chính xác tuyệt đối theo quy định mới nhất.', '[\"Phân quyền nhập điểm chặt chẽ theo bộ môn\",\"Khóa sổ điểm & nhật ký chỉnh sửa minh bạch\",\"Xuất phiếu báo điểm gửi Phụ huynh tự động\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('thcs', 2, '🗓️', '2. Xếp Thời khóa biểu AI & Phân công Chuyên môn', 'Thuật toán AI tối ưu hóa thời khóa biểu cho các tổ chuyên môn, xử lý môn Khoa học Tự nhiên, Lịch sử & Địa lý tích hợp không trùng tiết.', '[\"Hỗ trợ dạy học tích hợp liên môn\",\"Quản lý báo giảng & dạy thay tự động\",\"Theo dõi định mức tiết dạy của từng giáo viên\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('thcs', 3, '💻', '3. Kiểm tra Định kỳ & Học liệu Số Liên thông LMS', 'Kết nối trực tiếp với ngân hàng đề thi THCS để tổ chức kiểm tra 15 phút, giữa kỳ, cuối kỳ trên máy tính hoặc thiết bị di động.', '[\"Trộn đề trắc nghiệm & tự luận tự động\",\"Đồng bộ điểm thi trực tiếp vào Sổ điểm\",\"Phân tích phổ điểm theo từng khối lớp 6, 7, 8, 9\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('thcs', 4, '🧭', '4. Tư vấn Tâm lý Học đường & Phân luồng Lớp 9', 'Hỗ trợ học sinh khối 9 đánh giá năng lực bản thân, ôn thi tuyển sinh vào lớp 10 THPT và tư vấn định hướng nghề nghiệp sớm.', '[\"Thi thử tuyển sinh vào lớp 10 trực tuyến\",\"Gợi ý chọn tổ hợp môn THPT phù hợp năng lực\",\"Cổng tư vấn tâm lý học đường bảo mật\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('thcs', 5, '🔏', '5. Học bạ Số Ký số & Quản lý Xét Tốt nghiệp THCS', 'Tự động rà soát điều kiện xét công nhận tốt nghiệp THCS cho học sinh khối 9, phát hành Học bạ số có giá trị pháp lý toàn quốc.', '[\"Ký số USB Token / SmartCA cho BGH & GV\",\"Xét duyệt tốt nghiệp THCS chỉ với 1 cú nhấp\",\"In giấy chứng nhận tốt nghiệp tạm thời tự động\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('thcs', 6, '📲', '6. Điểm danh Thông minh & Tương tác Phụ huynh', 'Quản lý nền nếp chuyên cần của học sinh theo từng tiết học, cảnh báo tức thì nếu học sinh vắng không phép.', '[\"Điểm danh thẻ từ / khuôn mặt tại cổng trường\",\"Sổ đầu bài điện tử chấm điểm thi đua lớp\",\"Cổng thanh toán học phí không tiền mặt\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('thcs', 1, '🎓 Liên thông Tuyển sinh đầu cấp lên THPT (thpt)', 'Chuyển tiếp hồ sơ học bạ số và điểm xét tuyển của học sinh lớp 9 lên các trường THPT trong hệ thống.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('thcs', 2, '📝 Đồng bộ Ngân hàng Đề Khảo thí (lms)', 'Giáo viên THCS sử dụng chung kho học liệu và đề thi chuẩn hóa trên TechCorp LMS.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('thcs', 3, '🏫 Liên kết Luyện thi Tiếng Anh IELTS/TOEIC (ttnn)', 'Xác thực chứng chỉ ngoại ngữ quốc tế để xét tuyển thẳng hoặc cộng điểm khuyến khích.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_details` (`app_id`, `short_label`, `full_name`, `category_badge`, `app_url`, `target_audience`, `deploy_time`, `sso_scopes`, `preview_image`, `full_description`) VALUES ('thpt', '🎓 Trường THPT', 'EduManager Pro — Quản lý Trường THPT & Hướng nghiệp AI', '🏫 Khối Giáo dục K-12 (Trung học Phổ thông)', 'https://thpt.techcorp.info.vn', 'Trường THPT Công lập, Tư thục & Trường Chuyên', '15 phút (Chuẩn GDPT 2018 & Tốt nghiệp THPT)', 'TechCorp ID • GDPT 2018 • Hướng nghiệp AI', 'https://images.unsplash.com/photo-1523240795612-9a054b0db644?auto=format&fit=crop&w=1200&q=80', 'Nền tảng quản trị trường THPT thế hệ mới: Giải quyết triệt để bài toán đăng ký và xếp lớp Tổ hợp môn lựa chọn theo Chương trình GDPT 2018, luyện thi Tốt nghiệp THPT Quốc gia trên AI LMS và Hướng nghiệp Đại học cá nhân hóa.') ON DUPLICATE KEY UPDATE `short_label`=VALUES(`short_label`), `full_name`=VALUES(`full_name`), `category_badge`=VALUES(`category_badge`), `app_url`=VALUES(`app_url`), `target_audience`=VALUES(`target_audience`), `deploy_time`=VALUES(`deploy_time`), `sso_scopes`=VALUES(`sso_scopes`), `preview_image`=VALUES(`preview_image`), `full_description`=VALUES(`full_description`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('thpt', 1, '🧩', '1. Đăng ký & Xếp lớp Tổ hợp Môn GDPT 2018', 'Cho phép học sinh lớp 10 đăng ký nguyện vọng tổ hợp môn lựa chọn và chuyên đề học tập trực tuyến; AI tự động tối ưu hóa biên chế lớp.', '[\"Tối ưu theo đội ngũ giáo viên & phòng học bộ môn\",\"Quản lý lớp học chạy (Moving Class) linh hoạt\",\"Theo dõi lộ trình điểm số theo khối xét tuyển ĐH\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('thpt', 2, '🎯', '2. Luyện thi Tốt nghiệp THPT & Đánh giá Năng lực', 'Hệ thống thi thử trực tuyến chuẩn cấu trúc đề thi mới từ năm 2025 (Trắc nghiệm nhiều lựa chọn, Đúng/Sai, Trả lời ngắn).', '[\"Chấm điểm tự động & giải chi tiết bằng AI\",\"Thống kê lỗ hổng kiến thức từng chuyên đề\",\"Dự báo điểm thi Tốt nghiệp & khả năng đỗ Đại học\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('thpt', 3, '🤖', '3. Trợ lý AI Hướng nghiệp & Chọn Ngành Đại học', 'Trắc nghiệm đa trí thông minh (Holland, MBTI) kết hợp phân tích học lực thực tế để tư vấn ngành nghề và trường Đại học phù hợp nhất.', '[\"Tra cứu điểm chuẩn & phương thức xét tuyển ĐH\",\"Kết nối trực tiếp với hệ thống ĐH TC COMPASS\",\"Hồ sơ Năng lực Số (Talent Passport) cho học sinh\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('thpt', 4, '📊', '4. Sổ Điểm Điện tử, Học bạ Số & Quản lý Nền nếp', 'Quản lý toàn diện điểm số, hạnh kiểm, vi phạm nền nếp Đoàn trường và ký số Học bạ điện tử phục vụ xét tuyển Đại học.', '[\"Xuất dữ liệu xét học bạ Đại học chuẩn Bộ GD&ĐT\",\"Quản lý thi đua Đoàn Thanh niên Cộng sản HCM\",\"Thông báo chuyên cần thời gian thực tới Phụ huynh\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('thpt', 5, '👩‍🏫', '5. Quản trị Đội ngũ Giáo viên & Tổ Chuyên môn', 'Quản lý hồ sơ cán bộ giáo viên, sinh hoạt chuyên môn theo nghiên cứu bài học, lưu trữ sáng kiến kinh nghiệm và đánh giá chuẩn nghề nghiệp.', '[\"Kho bài giảng điện tử E-Learning dùng chung\",\"Quản lý lịch coi thi, chấm thi tập trung\",\"Đánh giá KPI & thi đua khen thưởng cuối năm\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('thpt', 6, '💳', '6. Quản lý Tài chính Học đường & Học bổng', 'Tự động hóa thu học phí, các khoản thu thỏa thuận, quản lý quỹ khuyến học và kết nối học bổng từ các Đại học/Doanh nghiệp thành viên.', '[\"Thanh toán VietQR gạch nợ tức thì\",\"Phát hành hóa đơn điện tử tự động\",\"Báo cáo quyết toán tài chính minh bạch\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('thpt', 1, '🧭 Liên thông Xét tuyển Đại học (qldt)', 'Đồng bộ kết quả học tập THPT và chứng chỉ ngoại ngữ lên cổng tuyển sinh các trường ĐH/CĐ dùng TC COMPASS.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('thpt', 2, '🏫 Săn Học bổng IELTS/SAT Quốc tế (ttnn)', 'Học sinh THPT nhận tài trợ thi thử IELTS/TOEIC và học bổng từ Liên minh Trung tâm Ngoại ngữ trên Hub.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('thpt', 3, '💻 Học Khóa Kỹ năng Số & AI Sớm (learn)', 'Truy cập kho khóa học lập trình, AI và ngoại ngữ trên TechCorpLearn bằng cùng một tài khoản TechCorp ID.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_details` (`app_id`, `short_label`, `full_name`, `category_badge`, `app_url`, `target_audience`, `deploy_time`, `sso_scopes`, `preview_image`, `full_description`) VALUES ('gdtx', '🏛️ GDNN - GDTX', 'EduManager Pro — Quản lý Trung tâm GDNN - GDTX', '🏫 Khối Giáo dục Thường xuyên & Dạy nghề', 'https://gdtx.techcorp.info.vn', 'Trung tâm GDNN - GDTX, Trường Trung cấp Nghề', '15 phút (Chuẩn Văn hóa GDTX + Liên kết Nghề)', 'TechCorp ID • Đào tạo Nghề • Việc làm', 'https://images.unsplash.com/photo-1581092160607-ee22621dd758?auto=format&fit=crop&w=1200&q=80', 'Hệ thống chuyên biệt cho các Trung tâm Giáo dục Nghề nghiệp - Giáo dục Thường xuyên: Quản lý song song chương trình Văn hóa GDTX cấp THPT và chương trình Liên kết Đào tạo Trung cấp nghề, cấp chứng chỉ nghề và kết nối việc làm doanh nghiệp.') ON DUPLICATE KEY UPDATE `short_label`=VALUES(`short_label`), `full_name`=VALUES(`full_name`), `category_badge`=VALUES(`category_badge`), `app_url`=VALUES(`app_url`), `target_audience`=VALUES(`target_audience`), `deploy_time`=VALUES(`deploy_time`), `sso_scopes`=VALUES(`sso_scopes`), `preview_image`=VALUES(`preview_image`), `full_description`=VALUES(`full_description`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('gdtx', 1, '📘', '1. Quản lý Song hành Văn hóa GDTX & Trung cấp Nghề', 'Theo dõi đồng thời kết quả học tập văn hóa 7 môn GDTX và tiến độ hoàn thành các mô-đun kỹ năng nghề của từng học viên.', '[\"Quản lý lớp liên kết với các trường Trung cấp/Cao đẳng\",\"Linh hoạt xếp lịch học văn hóa xen kẽ thực hành nghề\",\"Tự động tổng hợp điểm xét tốt nghiệp kép\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('gdtx', 2, '🛠️', '2. Quản lý Xưởng Thực hành & Nhật ký Thực tập', 'Quản lý vật tư tiêu hao tại xưởng thực hành (Điện, Cơ khí, Du lịch, Ẩm thực, CNTT) và nhật ký thực tập tại doanh nghiệp.', '[\"Theo dõi giờ thực hành tay nghề của học viên\",\"Doanh nghiệp xác nhận kết quả thực tập trực tuyến\",\"Quản lý an toàn lao động & thiết bị xưởng\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('gdtx', 3, '📜', '3. Quản lý Đào tạo Ngắn hạn & Cấp Chứng chỉ', 'Quản lý các lớp bồi dưỡng ngắn hạn (Tin học, Ngoại ngữ, Nghiệp vụ Sư phạm, Kỹ năng nghề), tổ chức thi sát hạch và cấp chứng chỉ QR.', '[\"Đăng ký học & nộp lệ phí thi trực tuyến\",\"In phôi chứng chỉ & tra cứu văn bằng chống giả\",\"Báo cáo đào tạo thường xuyên lên Sở GD&ĐT / Sở LĐTBXH\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('gdtx', 4, '🤝', '4. Cổng Kết nối Việc làm & Cung ứng Lao động Kỹ thuật', 'Đưa hồ sơ học viên tốt nghiệp nghề lên Sàn Tuyển dụng HireMind AI để kết nối thẳng với các Resort, Nhà máy và Doanh nghiệp SME.', '[\"1-Click ứng tuyển việc làm tại Khánh Hòa\",\"Theo dõi tỷ lệ học viên có việc làm sau tốt nghiệp\",\"Nhận đơn đặt hàng đào tạo từ Doanh nghiệp\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('gdtx', 5, '📲', '5. Điểm danh Chuyên cần & Kết nối Phụ huynh', 'Kiểm soát chặt chẽ giờ giấc ra vào của học viên, gửi thông báo tự động cho phụ huynh và giáo viên chủ nhiệm.', '[\"Điểm danh khuôn mặt AI hoặc thẻ học viên\",\"Quản lý nền nếp, nội quy trung tâm\",\"Cổng thu học phí văn hóa & học phí nghề tách biệt\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('gdtx', 6, '📈', '6. Báo cáo Điều hành Ban Giám đốc Trung tâm', 'Tổng hợp số liệu tuyển sinh đầu năm, tỷ lệ duy trì sĩ số, hiệu quả liên kết đào tạo và tài chính toàn trung tâm.', '[\"Biểu đồ biến động sĩ số theo từng khối/nghề\",\"Quản lý hợp đồng liên kết đào tạo với đối tác\",\"Xuất báo cáo chuẩn hóa nhanh chóng\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('gdtx', 1, '🤖 Đẩy Hồ sơ Học viên sang Sàn Việc làm (jobai)', 'Học viên hoàn thành chứng chỉ nghề được ưu tiên giới thiệu việc làm tại 30+ Doanh nghiệp trong hệ sinh thái.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('gdtx', 2, '🧭 Liên thông Cao đẳng / Đại học (qldt)', 'Hỗ trợ học viên tốt nghiệp GDTX + Trung cấp xét tuyển liên thông lên bậc Cao đẳng/Đại học.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('gdtx', 3, '🏢 Thực tập tại Khách sạn & Resort (qldh / erp)', 'Kết nối trực tiếp học viên ngành Du lịch, Nhà hàng, Kỹ thuật vào thực tập có lương tại các Resort.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_details` (`app_id`, `short_label`, `full_name`, `category_badge`, `app_url`, `target_audience`, `deploy_time`, `sso_scopes`, `preview_image`, `full_description`) VALUES ('qldt', '🧭 ĐH TC COMPASS', 'TC COMPASS — Quản trị Đại học & Đánh giá Hiệu suất', '🎓 Đại học, Cao đẳng & Học viện', 'https://qldt.techcorp.info.vn', 'Trường Đại học, Học viện, Trường Cao đẳng', 'Triển khai theo Khoa/Trường (Sẵn sàng Cloud)', 'TechCorp ID • Tín chỉ • KPI Giảng viên • Thực tập', 'https://images.unsplash.com/photo-1541339907198-e08756dedf3f?auto=format&fit=crop&w=1200&q=80', 'Hệ thống TC COMPASS v1.0 là nền tảng Quản trị Đại học số toàn diện kết hợp giữa Quản lý Đào tạo theo học chế tín chỉ, Đánh giá Hiệu suất KPI Giảng viên/Nghiên cứu khoa học, Kiểm định chất lượng giáo dục và Cổng Thực tập - Việc làm Sinh viên.') ON DUPLICATE KEY UPDATE `short_label`=VALUES(`short_label`), `full_name`=VALUES(`full_name`), `category_badge`=VALUES(`category_badge`), `app_url`=VALUES(`app_url`), `target_audience`=VALUES(`target_audience`), `deploy_time`=VALUES(`deploy_time`), `sso_scopes`=VALUES(`sso_scopes`), `preview_image`=VALUES(`preview_image`), `full_description`=VALUES(`full_description`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('qldt', 1, '🎓', '1. Quản trị Đào tạo Tín chỉ Toàn trình', 'Quản lý khung chương trình đào tạo (PLO/CLO), đăng ký học phần trực tuyến chịu tải cao, xếp lịch học - lịch thi và xét tốt nghiệp tự động.', '[\"Chuẩn đầu ra OBE (Outcome-Based Education)\",\"Cổng Sinh viên tra cứu điểm, học phí, tiến độ\",\"Quản lý văn bằng số & phụ lục văn bằng Blockchain/QR\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('qldt', 2, '📈', '2. Đánh giá Hiệu suất KPI Giảng viên & Viên chức', 'Tự động quy đổi giờ chuẩn giảng dạy, hướng dẫn khóa luận, bài báo khoa học (ISI/Scopus) và nhiệm vụ hành chính ra điểm KPI.', '[\"Theo dõi định mức giờ giảng & vượt giờ tự động\",\"Đánh giá đa chiều (Sinh viên - Bộ môn - Khoa)\",\"Liên thông trực tiếp với hệ thống TechCorp BSC-KPI\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('qldt', 3, '🔬', '3. Quản lý Nghiên cứu Khoa học & Hợp tác Quốc tế', 'Số hóa quy trình đăng ký đề tài NCKH các cấp, nghiệm thu đề tài, quản lý tạp chí khoa học, sáng chế và dự án hợp tác quốc tế.', '[\"Lý lịch khoa học điện tử của từng giảng viên\",\"Theo dõi tiến độ giải ngân kinh phí đề tài\",\"Kho lưu trữ công trình nghiên cứu & luận văn số\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('qldt', 4, '🏅', '4. Kiểm định Chất lượng Giáo dục (AUN-QA / Bộ GD&ĐT)', 'Hệ thống hóa kho minh chứng số phục vụ tự đánh giá và kiểm định chất lượng cơ sở giáo dục cũng như chương trình đào tạo.', '[\"Cây thư mục minh chứng số hóa thông minh\",\"Khảo sát ý kiến Sinh viên, Cựu SV & Nhà tuyển dụng\",\"Cảnh báo các chỉ số chất lượng cần cải tiến\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('qldt', 5, '💼', '5. Cổng Thực tập Doanh nghiệp & Hồ sơ Năng lực SV', 'Mỗi sinh viên sở hữu một Hồ sơ Năng lực Số (Talent Passport) tích hợp điểm GPA, kỹ năng ngoại ngữ/tin học để ứng tuyển thực tập 1-Click.', '[\"Doanh nghiệp đăng học kỳ doanh nghiệp (OJT)\",\"Chấm điểm thực tập trực tuyến giữa Khoa & DN\",\"Theo dõi việc làm của sinh viên sau khi ra trường\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('qldt', 6, '🏛️', '6. Dashboard Điều hành Chiến lược cho Ban Giám hiệu', 'Trung tâm dữ liệu lớn (University Data Warehouse) cung cấp chỉ số thời gian thực về tuyển sinh, tài chính, đội ngũ tiến sĩ/giảng viên và tỷ lệ tốt nghiệp.', '[\"Báo cáo Ba công khai & HEMIS Bộ GD&ĐT\",\"Phân tích tỷ lệ duy trì sinh viên theo từng ngành\",\"Tích hợp thu học phí ngân hàng tự động\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('qldt', 1, '🤖 Liên thông Sàn Tuyển dụng AI (jobai & erp)', 'Sinh viên năm cuối đẩy CV xác thực từ TC COMPASS sang thẳng HRM của Doanh nghiệp và Sàn HireMind AI.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('qldt', 2, '📝 Xác thực Chuẩn Đầu ra Ngoại ngữ - Tin học (lms)', 'Tự động đồng bộ kết quả thi chuẩn đầu ra TOEIC/IELTS/MOS từ TechCorp LMS về hồ sơ xét tốt nghiệp.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('qldt', 3, '📊 Đồng bộ Chiến lược Đại học (kpi)', 'Kết nối mục tiêu chiến lược của Hội đồng trường và Ban Giám hiệu với từng Khoa/Viện.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_details` (`app_id`, `short_label`, `full_name`, `category_badge`, `app_url`, `target_audience`, `deploy_time`, `sso_scopes`, `preview_image`, `full_description`) VALUES ('ttnn', '🏫 Trung tâm NN-TH', 'Quản lý Trung tâm Ngoại ngữ & Tin học Chuẩn Quốc tế', '🏫 Trung tâm Đào tạo Ngoại ngữ - Tin học - Kỹ năng', 'https://ttnn.techcorp.info.vn', 'Trung tâm Anh ngữ, Hàn/Nhật/Trung, Tin học & Kỹ năng', '15 phút (Sẵn sàng đa cơ sở / chuỗi trung tâm)', 'TechCorp ID • CRM Tuyển sinh • Phòng thi Online', 'https://images.unsplash.com/photo-1524178232363-1fb2b075b655?auto=format&fit=crop&w=1200&q=80', 'Giải pháp quản trị vận hành và tăng trưởng tuyển sinh đột phá dành cho các Trung tâm Ngoại ngữ, Tin học và Bồi dưỡng Kỹ năng: Kết hợp CRM chăm sóc học viên tiềm năng, xếp lịch giáo viên bản xứ/Việt Nam, quản lý học phí theo buổi/khóa và phòng thi thử IELTS/TOEIC.') ON DUPLICATE KEY UPDATE `short_label`=VALUES(`short_label`), `full_name`=VALUES(`full_name`), `category_badge`=VALUES(`category_badge`), `app_url`=VALUES(`app_url`), `target_audience`=VALUES(`target_audience`), `deploy_time`=VALUES(`deploy_time`), `sso_scopes`=VALUES(`sso_scopes`), `preview_image`=VALUES(`preview_image`), `full_description`=VALUES(`full_description`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('ttnn', 1, '🎯', '1. CRM Tuyển sinh Đa kênh & Quản lý Thi Xếp lớp', 'Thu thập tự động danh sách học viên tiềm năng (Leads) từ Website, Fanpage và các cuộc thi thử trên Hệ sinh thái TechCorp.', '[\"Phễu chăm sóc học viên (Tư vấn -> Thi thử -> Nhập học)\",\"Tổ chức bài thi Placement Test xếp lớp tự động\",\"Tính hoa hồng KPI cho đội ngũ Tư vấn viên (Sale)\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('ttnn', 2, '🗓️', '2. Quản lý Lớp học, Ca học & Lịch Giáo viên Bản xứ', 'Xếp lịch khai giảng, quản lý phòng học, phân bổ giờ dạy cho giáo viên Việt Nam, giáo viên nước ngoài và trợ giảng (TA).', '[\"Cảnh báo trùng lịch phòng học & giáo viên\",\"Quản lý học bù, bảo lưu, chuyển lớp linh hoạt\",\"Chấm công tính lương giáo viên theo giờ thực dạy\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('ttnn', 3, '🎧', '3. Phòng Luyện thi 4 Kỹ năng (IELTS / TOEIC / HSK / MOS)', 'Tích hợp môi trường luyện tập và thi thử trực tuyến chuẩn format quốc tế (Nghe - Nói - Đọc - Viết) có AI chấm chữa chi tiết.', '[\"AI chấm phát âm Speaking & sửa lỗi Writing\",\"Ngân hàng đề thi thử IELTS, TOEIC, TOPIK, MOS\",\"Cấp chứng nhận năng lực số có mã QR xác thực\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('ttnn', 4, '💳', '4. Quản lý Học phí, Gói học & Tự động Nhắc Gia hạn', 'Theo dõi số buổi học còn lại của từng học viên, tự động cảnh báo tư vấn viên và phụ huynh khi học viên sắp hết khóa để tái tục (Re-enroll).', '[\"Quản lý khuyến mãi, học bổng, voucher giảm giá\",\"Thu học phí VietQR & trả góp 0% lãi suất\",\"Báo cáo doanh thu thực thu và doanh thu phân bổ\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('ttnn', 5, '📱', '5. Sổ Liên lạc Học viên & Cổng Bài tập Về nhà', 'Học viên và phụ huynh theo dõi lịch học, điểm chuyên cần, video nhận xét của giáo viên sau mỗi buổi học và làm bài tập trực tuyến.', '[\"Thông báo điểm danh tức thì khi học viên vào lớp\",\"Xem lại tài liệu bài giảng & bài tập về nhà\",\"Đánh giá chất lượng buổi học sau mỗi ca\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('ttnn', 6, '🌐', '6. Quản trị Chuỗi Đa Cơ sở & Đồng Tổ chức Đấu trường', 'Giám đốc Trung tâm điều hành tập trung nhiều chi nhánh, đồng thời liên kết với các trường K12/Đại học tổ chức cuộc thi lớn.', '[\"Báo cáo so sánh hiệu quả giữa các cơ sở\",\"Đồng bộ thí sinh từ Đấu trường LMS về CRM\",\"Giới thiệu học viên xuất sắc sang Sàn Việc làm\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('ttnn', 1, '📝 Nhận Lead Học viên từ Đấu trường Thi (lms)', 'Mỗi khi tổ chức thi thử IELTS/TOEIC trên LMS, toàn bộ danh sách thí sinh được đồng bộ thẳng về CRM Trung tâm.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('ttnn', 2, '👶 Phát hành Học bổng sang Trường K12 (mamnon - thpt)', 'Gửi E-Voucher học bổng tiếng Anh trực tiếp tới hàng ngàn phụ huynh học sinh trong hệ sinh thái.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('ttnn', 3, '🤖 Giới thiệu Việc làm cho Học viên (jobai)', 'Học viên đạt chứng chỉ ngoại ngữ/tin học được gắn huy hiệu Xác thực trên Sàn Tuyển dụng HireMind AI.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_details` (`app_id`, `short_label`, `full_name`, `category_badge`, `app_url`, `target_audience`, `deploy_time`, `sso_scopes`, `preview_image`, `full_description`) VALUES ('lms', '📝 LMS & Khảo thí', 'TechCorp LMS & E-Testing — Đào tạo & Khảo thí Trực tuyến', '💻 Đào tạo Trực tuyến & Khảo thí Chuẩn hóa', 'https://lms.techcorp.info.vn', 'Trường học, Trung tâm Khảo thí, Doanh nghiệp Đào tạo Nội bộ', '10 phút (Chịu tải hàng ngàn thí sinh cùng lúc)', 'TechCorp ID • Anti-Cheat • QR Certificate', 'https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=1200&q=80', 'Nền tảng Quản lý Học tập (LMS) và Khảo thí Trực tuyến (E-Testing) chuyên nghiệp: Hỗ trợ tạo ngân hàng câu hỏi đa định dạng, trộn đề thông minh, giám sát phòng thi chống gian lận bằng AI và cấp Chứng chỉ Năng lực Số xác thực toàn hệ sinh thái.') ON DUPLICATE KEY UPDATE `short_label`=VALUES(`short_label`), `full_name`=VALUES(`full_name`), `category_badge`=VALUES(`category_badge`), `app_url`=VALUES(`app_url`), `target_audience`=VALUES(`target_audience`), `deploy_time`=VALUES(`deploy_time`), `sso_scopes`=VALUES(`sso_scopes`), `preview_image`=VALUES(`preview_image`), `full_description`=VALUES(`full_description`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('lms', 1, '🛡️', '1. Phòng Thi Trực tuyến Chống Gian lận (AI Proctoring)', 'Kiểm soát toàn diện tính minh bạch của kỳ thi: Khóa toàn màn hình, cảnh báo chuyển tab, giám sát qua Webcam và chống sao chép nội dung.', '[\"Tự động lưu bài làm mỗi 5 giây khi mất mạng\",\"Giới hạn IP phòng máy hoặc xác thực khuôn mặt\",\"Nhật ký hành vi thí sinh theo thời gian thực\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('lms', 2, '📚', '2. Ngân hàng Câu hỏi Đa định dạng & Ma trận Đề', 'Hỗ trợ đầy đủ các dạng câu hỏi hiện đại: Trắc nghiệm 1/nhiều đáp án, Đúng/Sai chùm, Điền khuyết, Ghép đôi, Nghe âm thanh, Đọc hiểu và Tự luận.', '[\"Import đề thi từ file Word / Excel trong 10 giây\",\"Sinh đề ngẫu nhiên theo ma trận 4 mức độ nhận thức\",\"Hỗ trợ công thức Toán/Lý/Hóa LaTeX sắc nét\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('lms', 3, '🏅', '3. Cấp Chứng chỉ Năng lực Số (Digital Badge & QR)', 'Ngay sau khi hoàn thành khóa học hoặc vượt qua kỳ thi sát hạch, hệ thống tự động cấp Chứng chỉ số có mã QR chống giả mạo.', '[\"Đồng bộ tự động vào Hồ sơ Năng lực Số ứng viên\",\"Nhà tuyển dụng quét QR xác thực điểm thi tức thì\",\"Tùy biến mẫu phôi chứng chỉ theo thương hiệu đơn vị\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('lms', 4, '🏆', '4. Tổ chức Đấu trường Thi Thử Quy mô Lớn', 'Công cụ tổ chức các cuộc thi Olympic, Rung chuông vàng, Đấu trường IELTS/TOEIC/Tin học cấp trường, liên trường hoặc toàn tỉnh.', '[\"Bảng xếp hạng (Leaderboard) cập nhật trực tiếp\",\"Thu hút học sinh/sinh viên & tạo phễu Tuyển sinh\",\"Tự động gửi Voucher học bổng cho thí sinh đạt giải\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('lms', 5, '🎓', '5. Quản lý Lớp học E-Learning & Lộ trình Học tập', 'Xây dựng khóa học trực tuyến kết hợp (Blended Learning) với bài giảng Video, SCORM, PDF, thảo luận và bài kiểm tra điều kiện qua môn.', '[\"Kiểm soát tiến độ xem video (chống tua nhanh)\",\"Tích hợp phòng học trực tuyến Zoom / Google Meet\",\"Nhắc lịch học & hạn nộp bài tự động\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('lms', 6, '📊', '6. Phân tích Phổ điểm & Đánh giá Độ khó Câu hỏi', 'Báo cáo thống kê khảo thí chuyên sâu giúp hội đồng chuyên môn đánh giá chất lượng đề thi và năng lực người học.', '[\"Biểu đồ phổ điểm, điểm trung bình, trung vị\",\"Phân tích tỷ lệ trả lời đúng từng câu hỏi\",\"Xuất bảng điểm chuẩn Excel / PDF ký số\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('lms', 1, '🤖 Xác thực Năng lực Ứng viên trên Sàn AI (jobai)', 'Điểm thi Ngoại ngữ, Tin học, Kế toán, Lập trình trên LMS được gắn nhãn \'Verified\' trong CV ứng viên.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('lms', 2, '🏫 Chuyển giao Thí sinh Tiềm năng về Trung tâm (ttnn)', 'Thí sinh tham gia thi thử có nhu cầu học nâng cao được chuyển thẳng về CRM của Trung tâm đào tạo.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('lms', 3, '🏢 Sát hạch Nhân sự Nội bộ Doanh nghiệp (erp)', 'Doanh nghiệp sử dụng LMS để đào tạo hội nhập (Onboarding) và thi nâng bậc nhân sự định kỳ.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_details` (`app_id`, `short_label`, `full_name`, `category_badge`, `app_url`, `target_audience`, `deploy_time`, `sso_scopes`, `preview_image`, `full_description`) VALUES ('learn', '💻 TechCorpLearn', 'TechCorpLearn — Nền tảng Học Trực tuyến & Khóa học Số', '💻 Cổng Học tập Trực tuyến & Kỹ năng Thực chiến', 'https://learn.techcorp.info.vn', 'Sinh viên, Người đi làm, Doanh nghiệp & Học viên Tự học', 'Truy cập học ngay 24/7 trên Web & Mobile', 'TechCorp ID • Video Courses • AI Tutor', 'https://images.unsplash.com/photo-1522202176988-66273c2fd55f?auto=format&fit=crop&w=1200&q=80', 'TechCorpLearn (\'Học để dẫn đầu\') là cổng học tập trực tuyến hiện đại cung cấp hàng trăm khóa học thực chiến về Trí tuệ Nhân tạo (AI), Lập trình, Quản trị Doanh nghiệp ERP/KPI, Nghiệp vụ Du lịch - Khách sạn, Ngoại ngữ và Kỹ năng Văn phòng.') ON DUPLICATE KEY UPDATE `short_label`=VALUES(`short_label`), `full_name`=VALUES(`full_name`), `category_badge`=VALUES(`category_badge`), `app_url`=VALUES(`app_url`), `target_audience`=VALUES(`target_audience`), `deploy_time`=VALUES(`deploy_time`), `sso_scopes`=VALUES(`sso_scopes`), `preview_image`=VALUES(`preview_image`), `full_description`=VALUES(`full_description`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('learn', 1, '🎬', '1. Thư viện Khóa học Video Tương tác Chất lượng Cao', 'Hệ thống bài giảng video Full HD được chia nhỏ theo phương pháp Micro-learning, đi kèm tài liệu thực hành, mã nguồn và bài tập tình huống.', '[\"Học mọi lúc mọi nơi trên Máy tính, Tablet, Điện thoại\",\"Ghi chú trực tiếp theo mốc thời gian video\",\"Bài kiểm tra ngắn (Quiz) sau mỗi chương học\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('learn', 2, '🗺️', '2. Lộ trình Học tập Theo Vị trí Công việc (Career Path)', 'Thiết kế lộ trình từ cơ bản đến chuyên sâu gắn liền với nhu cầu tuyển dụng thực tế của doanh nghiệp (VD: Chuyên viên ERP, Lễ tân Quốc tế, Digital Marketing).', '[\"Đánh giá năng lực đầu vào để gợi ý lộ trình\",\"Theo dõi % hoàn thành mục tiêu kỹ năng\",\"Cam kết chuẩn đầu ra sát với mô tả công việc\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('learn', 3, '🤖', '3. Trợ lý Học tập AI (AI Learning Mentor 24/7)', 'Giải đáp thắc mắc ngay lập tức trong lúc xem bài giảng, tóm tắt ý chính của bài học và tạo câu hỏi ôn tập thông minh.', '[\"Hỏi đáp kiến thức chuyên môn ngay bên cạnh video\",\"Gợi ý tài liệu đọc thêm và bài tập thực hành\",\"Hỗ trợ dịch thuật và luyện giao tiếp ngoại ngữ\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('learn', 4, '🏢', '4. Gói Đào tạo Doanh nghiệp (Corporate Academy)', 'Cung cấp tài khoản học tập theo lô cho Doanh nghiệp SME và Khách sạn/Resort để nâng cao năng lực đội ngũ nhân sự.', '[\"HR giao khóa học bắt buộc cho từng phòng ban\",\"Theo dõi giờ học & kết quả của từng nhân viên\",\"Tối ưu 70% chi phí tổ chức đào tạo nội bộ\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('learn', 5, '👨‍🏫', '5. Không gian Giảng viên & Chuyên gia Xuất bản Khóa học', 'Cho phép các Giảng viên Đại học, Giám đốc Trung tâm và Chuyên gia Doanh nghiệp dễ dàng đóng gói tri thức thành khóa học số.', '[\"Công cụ dựng khung chương trình trực quan\",\"Bảo vệ bản quyền video chống tải lậu (DRM)\",\"Chia sẻ doanh thu minh bạch trong Hệ sinh thái\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('learn', 6, '🎖️', '6. Chứng nhận Hoàn thành & Kết nối Tuyển dụng', 'Học viên hoàn thành khóa học được cấp Chứng nhận số và tự động gợi ý các vị trí việc làm phù hợp trên Sàn HireMind AI.', '[\"Tự động cập nhật kỹ năng mới vào CV số\",\"Ưu tiên phỏng vấn tại các doanh nghiệp đối tác\",\"Nhận ưu đãi nâng cấp khóa học chuyên sâu\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('learn', 1, '🤖 Tự động Gợi ý Việc làm Phù hợp (jobai)', 'Khi ứng viên còn thiếu kỹ năng so với JD tuyển dụng, HireMind AI sẽ gợi ý khóa học bổ sung trên TechCorpLearn.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('learn', 2, '📝 Thi Sát hạch Cấp Chứng chỉ Quốc gia (lms)', 'Học trên TechCorpLearn và đăng ký thi sát hạch tập trung trên TechCorp LMS.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('learn', 3, '📊 Gắn với Mục tiêu Học tập & Phát triển (kpi)', 'Kết quả hoàn thành khóa học được đồng bộ vào góc Học tập & Phát triển (L&D) trên hệ thống BSC-KPI.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_details` (`app_id`, `short_label`, `full_name`, `category_badge`, `app_url`, `target_audience`, `deploy_time`, `sso_scopes`, `preview_image`, `full_description`) VALUES ('kpi', '📊 BSC-KPI', 'TechCorp BSC-KPI — Quản trị Mục tiêu & Hiệu suất Thông minh', '🏢 Quản trị Chiến lược & Hiệu suất Doanh nghiệp', 'https://kpi.techcorp.info.vn', 'Doanh nghiệp SME, Tập đoàn, Trường ĐH & Tổ chức', '15 phút (Có sẵn thư viện 300+ chỉ số KPI theo ngành)', 'TechCorp ID • BSC Strategy • HRM Payroll Sync', 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&w=1200&q=80', 'Hệ thống Quản trị Chiến lược theo Thẻ điểm Cân bằng (Balanced Scorecard - BSC) và Đánh giá Hiệu suất KPI/OKR tự động: Giúp Ban lãnh đạo chuyển hóa tầm nhìn chiến lược thành mục tiêu đo lường được từ cấp Công ty xuống từng Phòng ban và Cá nhân.') ON DUPLICATE KEY UPDATE `short_label`=VALUES(`short_label`), `full_name`=VALUES(`full_name`), `category_badge`=VALUES(`category_badge`), `app_url`=VALUES(`app_url`), `target_audience`=VALUES(`target_audience`), `deploy_time`=VALUES(`deploy_time`), `sso_scopes`=VALUES(`sso_scopes`), `preview_image`=VALUES(`preview_image`), `full_description`=VALUES(`full_description`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('kpi', 1, '🧭', '1. Bản đồ Chiến lược BSC 4 Viễn cảnh', 'Thiết lập và trực quan hóa mục tiêu chiến lược theo 4 trụ cột: Tài chính, Khách hàng, Quy trình nội bộ và Học tập & Phát triển.', '[\"Liên kết nhân quả giữa các mục tiêu chiến lược\",\"Theo dõi sức khỏe chiến lược toàn công ty bằng màu sắc\",\"Phân bổ trọng số mục tiêu khoa học\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('kpi', 2, '🎯', '2. Phân rã KPI/OKR từ Công ty xuống Phòng ban & Cá nhân', 'Cơ chế giao chỉ tiêu (Cascading) linh hoạt theo tháng/quý/năm, đảm bảo mọi nhân viên đều hiểu rõ mục tiêu và trọng số công việc của mình.', '[\"Thư viện mẫu KPI cho Kinh doanh, Nhân sự, Kế toán, IT...\",\"Thiết lập công thức tính điểm tự động (Tăng/Giảm/Mốc)\",\"Phê duyệt bảng giao KPI trực tuyến đa cấp\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('kpi', 3, '⚡', '3. Cập nhật Kết quả Tự động & Minh chứng Công việc', 'Loại bỏ hoàn toàn tình trạng chấm điểm cảm tính cuối tháng nhờ cơ chế cập nhật tiến độ kèm file minh chứng hoặc kéo dữ liệu tự động từ ERP.', '[\"Đồng bộ doanh số từ CRM & tiến độ dự án từ ERP\",\"Cảnh báo sớm các chỉ số KPI có nguy cơ chậm tiến độ\",\"Hội đồng thẩm định & phản hồi trực tiếp trên từng chỉ số\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('kpi', 4, '💰', '4. Liên kết Điểm KPI với Lương Hiệu quả (3P Payroll)', 'Tự động quy đổi kết quả hoàn thành KPI (% KPI) thành hệ số thưởng hiệu suất, hoa hồng và bảng lương 3P hàng tháng.', '[\"Cấu hình thang xếp loại A+, A, B, C, D linh hoạt\",\"Tự động đẩy hệ số KPI sang bảng lương TechCorp ERP\",\"Minh bạch hóa thu nhập tạo động lực làm việc\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('kpi', 5, '🧬', '5. Khung Năng lực Nhân sự & Đánh giá 360 Độ', 'Đánh giá toàn diện thái độ, kỹ năng chuyên môn và năng lực lãnh đạo để quy hoạch đội ngũ kế cận và lập kế hoạch đào tạo.', '[\"Ma trận 9-Box đánh giá Hiệu suất × Tiềm năng\",\"Tự động gợi ý khóa học bù đắp thiếu hụt năng lực\",\"Lưu trữ lịch sử thăng tiến của từng nhân sự\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('kpi', 6, '📊', '6. Dashboard CEO & Báo cáo Phân tích Hiệu suất AI', 'Cung cấp góc nhìn toàn cảnh cho CEO và Giám đốc Nhân sự về năng suất lao động, top nhân sự xuất sắc và điểm nghẽn vận hành.', '[\"So sánh hiệu suất giữa các chi nhánh / phòng ban\",\"Trợ lý AI phân tích nguyên nhân không đạt chỉ tiêu\",\"Xuất báo cáo tổng kết quý/năm chỉ với 1 chạm\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('kpi', 1, '🏢 Đồng bộ Hai chiều với TechCorp ERP (erp)', 'Lấy số liệu thực tế từ CRM/Tài chính/Dự án trên ERP về chấm KPI và đẩy điểm KPI ngược lại phân hệ Tính lương HRM.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('kpi', 2, '🧭 Đánh giá KPI Giảng viên Đại học (qldt)', 'Tích hợp sâu với hệ thống TC COMPASS để quản trị KPI cho các trường Đại học, Cao đẳng.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('kpi', 3, '💻 Giao Khóa Đào tạo Khắc phục Điểm yếu (learn)', 'Nhân sự chưa đạt KPI kỹ năng được hệ thống tự động gán khóa học bồi dưỡng trên TechCorpLearn.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_details` (`app_id`, `short_label`, `full_name`, `category_badge`, `app_url`, `target_audience`, `deploy_time`, `sso_scopes`, `preview_image`, `full_description`) VALUES ('erp', '🏢 TechCorp ERP', 'TechCorp ERP — Quản trị Doanh nghiệp Tổng thể', '🏢 Hệ thống Hoạch định Nguồn lực Doanh nghiệp (All-in-One ERP)', 'https://erp.techcorp.info.vn', 'Doanh nghiệp SME, Thương mại, Dịch vụ, Sản xuất & Tập đoàn', '15 phút (Kiến trúc Modular bật/tắt linh hoạt)', 'TechCorp ID • HRM • CRM • Finance • Inventory', 'https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&w=1200&q=80', 'Nền tảng Quản trị Doanh nghiệp Hợp nhất (All-in-One Cloud ERP) giúp số hóa 100% quy trình vận hành: Từ Quản trị Nhân sự & Tuyển dụng (HRM), Chăm sóc Khách hàng & Bán hàng (CRM), Tài chính - Kế toán, Quản lý Kho vận - Mua hàng đến Quản lý Công việc & Dự án.') ON DUPLICATE KEY UPDATE `short_label`=VALUES(`short_label`), `full_name`=VALUES(`full_name`), `category_badge`=VALUES(`category_badge`), `app_url`=VALUES(`app_url`), `target_audience`=VALUES(`target_audience`), `deploy_time`=VALUES(`deploy_time`), `sso_scopes`=VALUES(`sso_scopes`), `preview_image`=VALUES(`preview_image`), `full_description`=VALUES(`full_description`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('erp', 1, '👥', '1. Quản trị Nhân sự Toàn trình (HRM & Payroll)', 'Quản lý hồ sơ nhân sự số, hợp đồng lao động, chấm công GPS/WiFi/FaceID, quản lý phép năm và tự động tính bảng lương - BHXH - Thuế TNCN.', '[\"1-Click nhập hồ sơ ứng viên từ Sàn HireMind AI\",\"Cổng Nhân viên tự phục vụ (Xin nghỉ, tăng ca, phiếu lương)\",\"Liên thông hệ số thưởng từ hệ thống BSC-KPI\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('erp', 2, '🤝', '2. Quản trị Khách hàng, Bán hàng & Marketing (CRM)', 'Quản lý tập trung dữ liệu khách hàng B2B/B2C, phễu cơ hội kinh doanh (Sales Pipeline), báo giá nhanh, hợp đồng và chăm sóc sau bán.', '[\"Phát hành E-Voucher ưu đãi lên Hệ sinh thái TechCorp\",\"Theo dõi lịch sử tương tác & công nợ từng khách hàng\",\"Dự báo doanh số theo nhân viên & khu vực\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('erp', 3, '💵', '3. Quản trị Tài chính - Kế toán & Dòng tiền', 'Kiểm soát thu chi, công nợ phải thu/phải trả, ngân sách phòng ban, phê duyệt đề nghị thanh toán trực tuyến và báo cáo lãi lỗ (P&L) tức thì.', '[\"Quy trình duyệt chi điện tử đa cấp không giấy tờ\",\"Đối soát dòng tiền ngân hàng thời gian thực\",\"Phân tích cấu trúc chi phí & biên lợi nhuận\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('erp', 4, '📦', '4. Quản lý Mua hàng, Kho vận & Chuỗi Cung ứng', 'Quản lý danh mục vật tư hàng hóa, định mức tồn kho tối thiểu, quy trình PR/PO mua hàng, nhập xuất tồn đa kho và kiểm kê mã vạch/QR.', '[\"Cảnh báo hàng sắp hết hoặc cận hạn sử dụng\",\"Đặt hàng nội bộ B2B giữa các doanh nghiệp trên Hub\",\"Tính giá vốn hàng xuất kho tự động\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('erp', 5, '📋', '5. Quản lý Dự án, Công việc & Quy trình Số (Workflow)', 'Giao việc theo bảng Kanban/Gantt, theo dõi tiến độ dự án, quản lý tài liệu dùng chung và số hóa mọi tờ trình phê duyệt nội bộ.', '[\"Nhắc việc tự động & đánh giá đúng hạn (SLA)\",\"Số hóa 100% đơn từ, đề xuất mua sắm, công tác\",\"Báo cáo hiệu suất xử lý công việc theo phòng ban\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('erp', 6, '👑', '6. Trung tâm Chỉ huy CEO (Executive BI Dashboard)', 'Tổng hợp mọi chỉ số sống còn của doanh nghiệp (Doanh thu, Dòng tiền, Tồn kho, Nhân sự, Công nợ) trên một màn hình duy nhất theo thời gian thực.', '[\"Truy cập phê duyệt mọi lúc mọi nơi trên điện thoại\",\"Phân quyền RBAC chi tiết đến từng nút bấm\",\"Nhật ký Audit Log truy vết an toàn dữ liệu\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('erp', 1, '🤖 Liên thông Tuyển dụng Nhân sự 1-Click (jobai)', 'Khi phòng ban phát sinh nhu cầu tuyển người trên ERP, tin tuyển dụng được đẩy thẳng lên Sàn HireMind AI và các trường Đại học.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('erp', 2, '📊 Đồng bộ Đánh giá Hiệu suất (kpi)', 'Kết nối dữ liệu doanh số/công việc từ ERP sang BSC-KPI để tính thưởng tự động.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('erp', 3, '🤝 Giao thương Nội bộ & Phát hành Voucher (Hub)', 'Gửi ưu đãi sản phẩm/dịch vụ của doanh nghiệp tới 3.500+ phụ huynh và thành viên trong hệ sinh thái.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_details` (`app_id`, `short_label`, `full_name`, `category_badge`, `app_url`, `target_audience`, `deploy_time`, `sso_scopes`, `preview_image`, `full_description`) VALUES ('jobai', '🤖 Sàn Việc làm AI', 'TechCorp HireMind AI — Sàn Tuyển dụng & Tìm việc AI ATS', '🤖 Sàn Tuyển dụng Thông minh & Quản trị Ứng viên AI ATS', 'https://jobai.techcorp.info.vn/careers.html', 'Doanh nghiệp Tuyển dụng, Trường ĐH/CĐ & Ứng viên / Sinh viên', 'Truy cập đăng tin & ứng tuyển ngay lập tức', 'TechCorp ID • AI Resume Parser • Verified Talent', 'https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=1200&q=80', 'Nền tảng Tuyển dụng & Tìm việc thế hệ mới tích hợp Trí tuệ Nhân tạo (AI ATS) đa ngôn ngữ (Việt - Anh - Hàn - Trung - Nhật): Tự động phân tích CV, chấm điểm mức độ phù hợp giữa Ứng viên với Mô tả công việc (JD) và xác thực văn bằng/chứng chỉ trực tiếp từ các Trường Đại học & Trung tâm đào tạo.') ON DUPLICATE KEY UPDATE `short_label`=VALUES(`short_label`), `full_name`=VALUES(`full_name`), `category_badge`=VALUES(`category_badge`), `app_url`=VALUES(`app_url`), `target_audience`=VALUES(`target_audience`), `deploy_time`=VALUES(`deploy_time`), `sso_scopes`=VALUES(`sso_scopes`), `preview_image`=VALUES(`preview_image`), `full_description`=VALUES(`full_description`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('jobai', 1, '🧠', '1. AI Phân tích CV & Chấm điểm Phù hợp (AI Matching Score)', 'Công nghệ AI đọc hiểu sâu hồ sơ ứng viên (PDF/Word) và so khớp tự động với yêu cầu tuyển dụng để xếp hạng ứng viên theo % độ tương thích.', '[\"Tự động bóc tách kỹ năng, kinh nghiệm, học vấn\",\"Phát hiện điểm mạnh & điểm thiếu hụt của ứng viên\",\"Tiết kiệm 85% thời gian lọc CV cho bộ phận HR\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('jobai', 2, '✅', '2. Hồ sơ Năng lực Số Đã Xác thực (Verified Talent Passport)', 'Khác biệt hoàn toàn với các sàn việc làm truyền thống: Điểm GPA, chứng chỉ IELTS/TOEIC/MOS và tay nghề của ứng viên được xác thực trực tiếp từ Trường học & LMS.', '[\"Huy hiệu \'Xác thực bởi TechCorp ID\' chống khai khống CV\",\"Đính kèm kết quả bài thi thực tế trên TechCorp LMS\",\"Tăng gấp 3 lần tỷ lệ được doanh nghiệp mời phỏng vấn\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('jobai', 3, '📋', '3. Hệ thống Quản trị Tuyển dụng Doanh nghiệp (ATS Pipeline)', 'Cung cấp bảng Kanban quản lý toàn bộ quy trình tuyển dụng: Từ Nhận hồ sơ -> Sàng lọc AI -> Test năng lực -> Phỏng vấn -> Gửi Offer -> Onboarding.', '[\"Đặt lịch phỏng vấn tự động & gửi email thông báo\",\"Hội đồng phỏng vấn chấm điểm ứng viên trực tuyến\",\"1-Click chuyển ứng viên trúng tuyển sang HRM của ERP\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('jobai', 4, '🌍', '4. Hỗ trợ Đa Ngôn ngữ cho Du lịch, FDI & Quốc tế', 'Giao diện và công cụ AI hỗ trợ 5 ngôn ngữ (Tiếng Việt, Anh, Hàn, Trung, Nhật), đặc biệt tối ưu cho các Resort, Khách sạn quốc tế và doanh nghiệp FDI.', '[\"Tạo & dịch tin tuyển dụng đa ngôn ngữ tự động\",\"Sàng lọc ứng viên thôngạo ngoại ngữ chuẩn xác\",\"Phỏng vấn sơ loại tự động bằng AI\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('jobai', 5, '🎓', '5. Cổng Kết nối Thực tập & Việc làm Sinh viên Đại học', 'Không gian chuyên biệt kết nối Phòng Công tác Sinh viên các trường Đại học, Cao đẳng, GDTX với hàng trăm doanh nghiệp đang khát nhân lực.', '[\"Ngày hội Việc làm Trực tuyến (Virtual Job Fair)\",\"Chương trình Học kỳ Doanh nghiệp & Thực tập sinh\",\"Báo cáo thống kê việc làm sinh viên cho Nhà trường\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('jobai', 6, '✨', '6. Trợ lý AI Tạo CV Chuẩn ATS & Gợi ý Lộ trình Kỹ năng', 'Hỗ trợ người tìm việc và sinh viên khởi tạo CV chuyên nghiệp trong 2 phút, đồng thời gợi ý các khóa học ngắn hạn để nâng mức lương kỳ vọng.', '[\"Tối ưu từ khóa CV vượt qua mọi hệ thống ATS\",\"Gợi ý việc làm cá nhân hóa theo năng lực thực\",\"Kết nối học nâng cấp kỹ năng trên TechCorpLearn\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('jobai', 1, '🏢 Đồng bộ Nhân sự Trúng tuyển về ERP (erp)', 'Ứng viên nhận Offer trên HireMind AI được khởi tạo hồ sơ nhân viên tự động trên TechCorp ERP mà không cần nhập lại.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('jobai', 2, '🧭 Nhận Nguồn Sinh viên từ Đại học (qldt & gdtx)', 'Liên thông trực tiếp với cổng thực tập của các trường Đại học, Cao đẳng và Trung tâm GDNN-GDTX.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('jobai', 3, '📝 Kèm Bài Test Tuyển dụng Trực tuyến (lms)', 'Nhà tuyển dụng gắn bài thi IQ, Ngoại ngữ hoặc Chuyên môn từ TechCorp LMS ngay trong tin đăng tuyển.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_details` (`app_id`, `short_label`, `full_name`, `category_badge`, `app_url`, `target_audience`, `deploy_time`, `sso_scopes`, `preview_image`, `full_description`) VALUES ('techcorp', '🌐 TechCorp Academy', 'TechCorp Academy — Giải pháp PMS, ERP, LMS & Đào tạo', '🌐 Cổng Giải pháp Công nghệ & Tư vấn Chuyển đổi Số', 'https://techcorp.info.vn', 'Doanh nghiệp, Cơ sở Giáo dục, Khách sạn & Đối tác Chiến lược', 'Tư vấn & Khởi tạo Giải pháp May đo Toàn diện', 'TechCorp ID • Digital Consulting • Academy', 'https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=1200&q=80', 'Cổng thông tin chính thức của Công ty TNHH Công nghệ và Giáo dục TechCorp (TechCorp Academy): Trung tâm tư vấn chiến lược chuyển đổi số, cung cấp các gói giải pháp phần mềm quản trị PMS, ERP, KPI, LMS và đào tạo nhân lực ứng dụng AI thực chiến.') ON DUPLICATE KEY UPDATE `short_label`=VALUES(`short_label`), `full_name`=VALUES(`full_name`), `category_badge`=VALUES(`category_badge`), `app_url`=VALUES(`app_url`), `target_audience`=VALUES(`target_audience`), `deploy_time`=VALUES(`deploy_time`), `sso_scopes`=VALUES(`sso_scopes`), `preview_image`=VALUES(`preview_image`), `full_description`=VALUES(`full_description`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('techcorp', 1, '🏛️', '1. Tư vấn Kiến trúc Chuyển đổi Số Toàn diện', 'Khảo sát quy trình thực tế tại Doanh nghiệp/Trường học, thiết kế lộ trình số hóa từng bước giúp tối ưu chi phí và cam kết hiệu quả đầu tư (ROI).', '[\"Đánh giá mức độ trưởng thành số miễn phí\",\"May đo phần mềm theo đặc thù riêng của đơn vị\",\"Đội ngũ chuyên gia đồng hành trực tiếp tại Khánh Hòa & Hà Nội\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('techcorp', 2, '📦', '2. Các Gói Combo Giải pháp Hạt nhân Tiết kiệm', 'Đóng gói sẵn các bộ giải pháp liên hoàn: Gói Mầm non Số, Gói Tăng tốc Trung tâm Ngoại ngữ, Gói Bệ phóng SME và Gói Quản trị Resort.', '[\"Tài trợ 100% phí khởi tạo cho đơn vị hạt nhân\",\"Tặng kèm Website chuẩn SEO tích hợp CRM\",\"Dùng chung 01 định danh SSO cho toàn bộ phần mềm\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('techcorp', 3, '🤖', '3. Đào tạo Ứng dụng AI & Quản trị Thực chiến', 'Tổ chức các chương trình huấn luyện In-house cho Ban Giám đốc, Quản lý cấp trung và Giáo viên về ứng dụng AI trong công việc hàng ngày.', '[\"AI cho Lãnh đạo & Quản trị Nhân sự, Marketing\",\"AI cho Giáo viên soạn giảng & khảo thí hiện đại\",\"Chuyển giao quy trình vận hành chuẩn trên ERP/KPI\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('techcorp', 4, '🔗', '4. Dịch vụ Tích hợp Hệ thống & Open API', 'Cung cấp cổng kết nối API tiêu chuẩn để tích hợp hệ thống TechCorp với Hóa đơn điện tử, Ngân hàng VietQR, Thiết bị chấm công và Camera AI.', '[\"Tích hợp máy chấm công FaceID / Vân tay\",\"Kết nối cổng thanh toán Ngân hàng tự động\",\"Đảm bảo an toàn bảo mật dữ liệu chuẩn Quốc tế\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('techcorp', 5, '🛠️', '5. Trung tâm Hỗ trợ Kỹ thuật & Chăm sóc Khách hàng 24/7', 'Cam kết SLA vận hành ổn định 99.9%, hỗ trợ kỹ thuật tức thì qua Zalo/Hotline và nâng cấp tính năng định kỳ miễn phí.', '[\"Đội ngũ kỹ sư hỗ trợ tận nơi tại Nha Trang - Khánh Hòa\",\"Sao lưu dữ liệu tự động hàng ngày đa vùng\",\"Tài liệu & video hướng dẫn sử dụng trực quan\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('techcorp', 6, '🤝', '6. Mạng lưới Đối tác & Cộng đồng Doanh nghiệp TechCorp', 'Kết nối các đơn vị sử dụng phần mềm TechCorp thành một liên minh giao thương bền vững, cùng chia sẻ khách hàng và nguồn nhân lực.', '[\"Tham gia Diễn đàn Giao thương B2B miễn phí\",\"Đồng tổ chức sự kiện, hội thảo chuyển đổi số\",\"Hưởng chiết khấu đặc quyền từ toàn bộ hệ sinh thái\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('techcorp', 1, '🌐 Trung tâm Điều phối 16 Sản phẩm Live', 'Kết nối xuyên suốt toàn bộ các nền tảng Giáo dục K12, Đại học, LMS, ERP, KPI, PMS, BĐS và Nội thất.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('techcorp', 2, '📋 Đồng bộ Yêu cầu Tư vấn về Admin CRM', 'Mọi đăng ký tư vấn và Demo từ khách hàng đều được quản lý tập trung tại trang Quản trị Hệ sinh thái.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('techcorp', 3, '🎓 Liên kết Đào tạo & Cung ứng Nhân sự', 'Đào tạo nhân sự biết sử dụng thành thạo phần mềm ERP/PMS/LMS trước khi bàn giao cho doanh nghiệp.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_details` (`app_id`, `short_label`, `full_name`, `category_badge`, `app_url`, `target_audience`, `deploy_time`, `sso_scopes`, `preview_image`, `full_description`) VALUES ('qldh', '🏨 Khách sạn PMS', 'TechCorp PMS — Hệ thống Quản lý Khách sạn & Resort', '🏨 Giải pháp Chuyên ngành Du lịch - Khách sạn & Resort', 'https://qldh.techcorp.info.vn', 'Khách sạn 3-5 Sao, Resort, Villa, Homestay & Chuỗi Lưu trú', '15 phút (Sẵn sàng Sơ đồ Phòng & POS Nhà hàng)', 'TechCorp ID • Front Office • Housekeeping • POS', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1200&q=80', 'Phần mềm Quản lý Khách sạn & Khu nghỉ dưỡng (Property Management System - PMS) toàn diện: Tối ưu hóa công suất phòng từ Đặt phòng (Reservation), Lễ tân Check-in/Check-out siêu tốc, Quản lý Buồng phòng (Housekeeping), POS Nhà hàng - Spa đến Quản trị Doanh thu.') ON DUPLICATE KEY UPDATE `short_label`=VALUES(`short_label`), `full_name`=VALUES(`full_name`), `category_badge`=VALUES(`category_badge`), `app_url`=VALUES(`app_url`), `target_audience`=VALUES(`target_audience`), `deploy_time`=VALUES(`deploy_time`), `sso_scopes`=VALUES(`sso_scopes`), `preview_image`=VALUES(`preview_image`), `full_description`=VALUES(`full_description`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('qldh', 1, '🛎️', '1. Nghiệp vụ Lễ tân & Sơ đồ Phòng Trực quan (Front Office)', 'Quản lý sơ đồ phòng theo thời gian thực (Trống, Đang ở, Đặt trước, Đang dọn, Bảo trì), thực hiện Check-in/Check-out khách lẻ và khách đoàn (Group) chỉ trong vài giây.', '[\"Quét CCCD / Hộ chiếu tự động điền thông tin khách\",\"Chuyển phòng, nâng hạng phòng, gộp/tách hóa đơn linh hoạt\",\"Khai báo lưu trú trực tuyến tự động\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('qldh', 2, '📅', '2. Quản lý Đặt phòng Đa kênh & Đại lý Du lịch (OTA / TA)', 'Kiểm soát quỹ phòng (Allotment), bảng giá linh hoạt theo mùa cao điểm/thấp điểm, quản lý hợp đồng đại lý lữ hành (Traveloka, Booking, Agoda, TA).', '[\"Tránh tuyệt đối tình trạng Overbooking\",\"Cấu hình gói Combo Phòng + Ăn sáng + Đưa đón sân bay\",\"Theo dõi công nợ các công ty lữ hành minh bạch\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('qldh', 3, '🧹', '3. Quản lý Buồng phòng Thông minh (Housekeeping & Minibar)', 'Nhân viên buồng phòng cập nhật trạng thái dọn phòng và tiêu dùng Minibar/Giặt là ngay trên điện thoại, đồng bộ tức thì về quầy Lễ tân.', '[\"Chốt số lượng đồ uống Minibar trước khi khách trả phòng\",\"Quản lý đồ thất lạc (Lost & Found) và vật tư tiêu hao\",\"Lập lịch bảo trì định kỳ điều hòa, thiết bị phòng\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('qldh', 4, '🍽️', '4. Phân hệ POS Nhà hàng, Bar, Banquet & Spa', 'Gọi món tại bàn, quản lý buffet sáng bằng mã QR/thẻ phòng, cho phép khách ký bill chuyển thẳng chi phí dịch vụ về hóa đơn phòng (Post to Room).', '[\"Định lượng nguyên vật liệu bếp & trừ kho tự động\",\"Quản lý sảnh tiệc hội nghị, gala dinner, đám cưới\",\"Đặt lịch kỹ thuật viên Spa & tính hoa hồng dịch vụ\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('qldh', 5, '📊', '5. Kiểm toán Đêm (Night Audit) & Báo cáo Quản trị GM', 'Tự động chạy kiểm toán đêm, chốt doanh thu phòng - dịch vụ và cung cấp bộ chỉ số chuẩn khách sạn quốc tế (Occupancy, ADR, RevPAR).', '[\"Biểu đồ công suất phòng dự báo 30 - 90 ngày tới\",\"Phân tích nguồn khách theo quốc tịch & kênh bán\",\"Xuất hóa đơn điện tử GTGT kết nối cơ quan thuế\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('qldh', 6, '👥', '6. Quản lý Nhân sự Ca kíp & Tuyển dụng Du lịch', 'Phân ca làm việc 24/7 cho Lễ tân, Buồng phòng, An ninh, Nhà hàng và kết nối trực tiếp với nguồn sinh viên thực tập ngành Du lịch.', '[\"Chấm công theo ca gãy / ca đêm đặc thù khách sạn\",\"Đánh giá KPI chất lượng phục vụ khách hàng\",\"Tuyển nhân sự thời vụ & chính thức qua Sàn HireMind AI\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('qldh', 1, '🤖 Tuyển Nhân sự Lễ tân Ngoại ngữ (jobai & ttnn)', 'Kết nối thẳng với các Trung tâm Tiếng Anh/Hàn/Trung và Trường CĐ/ĐH Du lịch để tuyển nhân sự đã xác thực ngoại ngữ.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('qldh', 2, '🎁 Phát hành E-Voucher Nghỉ dưỡng & Dã ngoại (Hub)', 'Tung gói ưu đãi Tour học đường, Teambuilding và Voucher nghỉ dưỡng tới 30+ Trường học & Doanh nghiệp trên Hub.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('qldh', 3, '🏢 Đồng bộ Kế toán & Kho Tổng (erp)', 'Dữ liệu doanh thu và xuất nhập tồn F&B từ PMS được đồng bộ tự động về hệ thống TechCorp ERP.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_details` (`app_id`, `short_label`, `full_name`, `category_badge`, `app_url`, `target_audience`, `deploy_time`, `sso_scopes`, `preview_image`, `full_description`) VALUES ('bds', '🏙️ BĐS Hưng Phát AI', 'Hưng Phát Land — Sàn Giao dịch Bất động sản & Trợ lý AI', '🏙️ Giải pháp Chuyên ngành Bất động sản & PropTech AI', 'https://bds.techcorp.info.vn', 'Sàn Giao dịch BĐS, Chủ đầu tư Dự án, Đơn vị Môi giới & Đầu tư', '15 phút (Tích hợp sẵn Giỏ hàng & Trợ lý AI 24/7)', 'TechCorp ID • PropTech CRM • AI Real Estate Advisor', 'https://images.unsplash.com/photo-1560518883-ce09059eeffa?auto=format&fit=crop&w=1200&q=80', 'Nền tảng Sàn Giao dịch Bất động sản số hóa tích hợp Trợ lý AI tư vấn 24/7 (Hưng Phát Land PropTech): Quản lý bảng hàng dự án theo thời gian thực, CRM chăm sóc nhà đầu tư, định giá tham chiếu AI, tra cứu pháp lý quy hoạch và tính hoa hồng môi giới tự động.') ON DUPLICATE KEY UPDATE `short_label`=VALUES(`short_label`), `full_name`=VALUES(`full_name`), `category_badge`=VALUES(`category_badge`), `app_url`=VALUES(`app_url`), `target_audience`=VALUES(`target_audience`), `deploy_time`=VALUES(`deploy_time`), `sso_scopes`=VALUES(`sso_scopes`), `preview_image`=VALUES(`preview_image`), `full_description`=VALUES(`full_description`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('bds', 1, '🏙️', '1. Quản lý Giỏ hàng Dự án & Bảng hàng Trực tuyến (Real-time)', 'Hiển thị trực quan mặt bằng phân lô, tòa căn hộ theo mã màu (Còn trống, Đang giữ chỗ/Lock, Đã cọc, Đã ký HĐMB) giúp chuyên viên chốt căn tức thì.', '[\"Giữ chỗ (Booking/Lock căn) trực tuyến có đếm ngược\",\"Thư viện ảnh 360°, video thực tế, mặt bằng 3D từng căn\",\"Chính sách bán hàng & bảng tính dòng tiền vay ngân hàng\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('bds', 2, '🤖', '2. Trợ lý AI Tư vấn Bất động sản 24/7', 'Chatbot AI thông minh tự động tư vấn sản phẩm phù hợp theo tầm tài chính, nhu cầu ở thực hoặc đầu tư sinh lời, hướng phong thủy và pháp lý dự án.', '[\"Gợi ý bất động sản chuẩn xác chỉ sau 3 câu hỏi\",\"Tự động đặt lịch dẫn khách đi xem thực tế (Site Tour)\",\"Thu thập thông tin khách hàng tiềm năng về CRM 24/7\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('bds', 3, '📈', '3. CRM Bất động sản & Chăm sóc Nhà đầu tư VIP', 'Phân loại khách hàng theo mức độ quan tâm (Nóng - Ấm - Lạnh), phân bổ Lead tự động cho chuyên viên kinh doanh và bảo mật thông tin khách hàng tuyệt đối.', '[\"Ẩn số điện thoại khách hàng chống rò rỉ dữ liệu\",\"Nhắc lịch chăm sóc khách hàng và lịch thanh toán theo tiến độ\",\"Tự động gửi thông tin dự án mới cho tệp nhà đầu tư cũ\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('bds', 4, '📜', '4. Quản lý Giao dịch, Hợp đồng & Hồ sơ Pháp lý Số', 'Số hóa toàn bộ quy trình từ Phiếu giữ chỗ -> Hợp đồng Đặt cọc -> Hợp đồng Mua bán -> Công chứng sang tên và bàn giao sổ hồng.', '[\"Lưu trữ hồ sơ pháp lý dự án (1/500, GPXD, Sổ đỏ)\",\"Theo dõi tiến độ thanh toán từng đợt của khách hàng\",\"In hợp đồng & phiếu thu tự động theo mẫu chuẩn\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('bds', 5, '💎', '5. Tính Hoa hồng Môi giới, Thưởng Nóng & Đội nhóm', 'Tự động tính toán hoa hồng bán hàng cho Chuyên viên, Trưởng phòng, Giám đốc sàn và các sàn liên kết (F1/F2) ngay khi giao dịch thành công.', '[\"Cấu hình cơ chế hoa hồng lũy tiến đa tầng\",\"Bảng xếp hạng Best Seller vinh danh theo tuần/tháng\",\"Đối soát tạm ứng & thanh toán hoa hồng minh bạch\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('bds', 6, '🛋️', '6. Liên kết Hoàn thiện Nội thất & Khai thác Cho thuê', 'Sau khi khách hàng mua căn hộ/biệt thự, hệ thống tự động kết nối gói Thiết kế - Thi công Nội thất và dịch vụ Quản lý Vận hành Cho thuê.', '[\"Tặng Voucher thiết kế nội thất 3D trên hệ sinh thái\",\"Ủy thác vận hành căn hộ du lịch trên TechCorp PMS\",\"Gia tăng giá trị trọn đời cho khách hàng (LTV)\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('bds', 1, '🛋️ Liên thông Thiết kế & Thi công Nội thất (noithat)', 'Khách mua nhà trên sàn BĐS được chuyển tiếp nhận gói tư vấn và ưu đãi nội thất từ TechCorp Interior.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('bds', 2, '🏨 Ủy thác Khai thác Lưu trú Du lịch (qldh)', 'Chủ sở hữu căn hộ biển/biệt thự nghỉ dưỡng kết nối trực tiếp vào hệ thống quản lý vận hành khách sạn PMS.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('bds', 3, '🏢 Quản trị Tài chính & Nhân sự Sàn (erp & kpi)', 'Đồng bộ doanh số giao dịch BĐS về hệ thống ERP và đánh giá KPI đội ngũ kinh doanh.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_details` (`app_id`, `short_label`, `full_name`, `category_badge`, `app_url`, `target_audience`, `deploy_time`, `sso_scopes`, `preview_image`, `full_description`) VALUES ('noithat', '🛋️ Nội thất 3D', 'TechCorp Interior — Thiết kế, Thi công & Showroom Nội thất', '🛋️ Giải pháp Chuyên ngành Kiến trúc, Nội thất & Xây dựng', 'https://noithat.techcorp.info.vn', 'Công ty Thiết kế - Thi công Nội thất, Showroom, Xưởng Sản xuất', '15 phút (Có sẵn Catalog Nội thất & Công cụ Dự toán)', 'TechCorp ID • 3D Catalog • BOQ Quotation • Project', 'https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&w=1200&q=80', 'Nền tảng Kiến tạo Không gian Hoàn mỹ (TechCorp Interior): Kết hợp Showroom trưng bày sản phẩm nội thất trực tuyến, quản lý thư viện thiết kế 3D theo phong cách, lập bảng báo giá dự toán (BOQ) tự động, quản lý sản xuất tại xưởng và giám sát tiến độ thi công lắp đặt công trình.') ON DUPLICATE KEY UPDATE `short_label`=VALUES(`short_label`), `full_name`=VALUES(`full_name`), `category_badge`=VALUES(`category_badge`), `app_url`=VALUES(`app_url`), `target_audience`=VALUES(`target_audience`), `deploy_time`=VALUES(`deploy_time`), `sso_scopes`=VALUES(`sso_scopes`), `preview_image`=VALUES(`preview_image`), `full_description`=VALUES(`full_description`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('noithat', 1, '🛋️', '1. Showroom Nội thất Trực tuyến & Thư viện Ý tưởng 3D', 'Trưng bày hàng ngàn sản phẩm nội thất rời và các gói combo thiết kế trọn gói (Căn hộ, Biệt thự, Khách sạn, Văn phòng, Trường học) sắc nét.', '[\"Bộ lọc theo Phong cách (Modern, Luxury, Indochine, Japandi)\",\"Xem chi tiết kích thước, chất liệu gỗ, đá, phụ kiện\",\"Giỏ hàng đặt mua lẻ hoặc đăng ký tư vấn thiết kế\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('noithat', 2, '📐', '2. Lập Báo giá Dự toán Thiết kế & Thi công Tự động (BOQ)', 'Kiến trúc sư và tư vấn viên lập bảng dự toán chi tiết từng hạng mục phòng khách, phòng bếp, phòng ngủ theo kích thước thực tế chỉ trong 5 phút.', '[\"Tự động tính diện tích (m², md) và đơn giá vật liệu\",\"Thay đổi vật liệu (Gỗ An Cường, Sơn, Phụ kiện Hafele/Blum) cập nhật giá tức thì\",\"Xuất file báo giá PDF chuyên nghiệp mang thương hiệu công ty\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('noithat', 3, '🎨', '3. Quản lý Quy trình Thiết kế 2D/3D & Duyệt Bản vẽ', 'Theo dõi sát sao quy trình từ Khảo sát hiện trạng -> Mặt bằng 2D -> Phối cảnh 3D -> Bản vẽ Kỹ thuật thi công (Shop Drawing) với khách hàng.', '[\"Khách hàng phản hồi & duyệt phương án 3D trực tuyến\",\"Lưu trữ lịch sử các phiên bản chỉnh sửa bản vẽ\",\"Tính KPI tiến độ bàn giao hồ sơ thiết kế cho Kiến trúc sư\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('noithat', 4, '🏭', '4. Quản lý Đặt hàng Xưởng Sản xuất & Kho Vật tư', 'Chuyển bảng bóc tách vật tư từ bản vẽ kỹ thuật xuống Xưởng mộc/Xưởng nội thất để cắt ván, gia công, kiểm tra chất lượng (QC) và đóng gói.', '[\"Quản lý tồn kho ván gỗ, phụ kiện, thiết bị bếp\",\"Theo dõi tiến độ sản xuất từng đơn hàng tại xưởng\",\"Giảm thiểu tối đa sai sót và hao hụt vật tư\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('noithat', 5, '👷', '5. Giám sát Thi công Lắp đặt Công trình & Nghiệm thu', 'Kỹ sư giám sát cập nhật hình ảnh nhật ký thi công hàng ngày tại công trình, theo dõi các mốc nghiệm thu và thu tiền theo từng giai đoạn hợp đồng.', '[\"Cổng Khách hàng xem trực tiếp tiến độ hoàn thiện nhà\",\"Biên bản nghiệm thu từng hạng mục điện tử\",\"Cảnh báo các hạng mục có nguy cơ trễ hạn bàn giao\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_modules` (`app_id`, `module_order`, `icon`, `title`, `description`, `bullets_json`) VALUES ('noithat', 6, '🛡️', '6. Quản lý Bảo hành Điện tử & Chăm sóc Sau Bàn giao', 'Mỗi công trình hoặc sản phẩm nội thất được cấp sổ bảo hành điện tử QR, giúp khách hàng gửi yêu cầu bảo trì bảo dưỡng nhanh chóng.', '[\"Quét QR tra cứu thời hạn bảo hành từng thiết bị\",\"Điều phối đội kỹ thuật bảo hành trong 24h\",\"Xây dựng uy tín thương hiệu & gia tăng khách hàng giới thiệu\"]') ON DUPLICATE KEY UPDATE `icon`=VALUES(`icon`), `title`=VALUES(`title`), `description`=VALUES(`description`), `bullets_json`=VALUES(`bullets_json`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('noithat', 1, '🏙️ Nhận Nguồn Khách Mua Nhà từ Sàn BĐS (bds)', 'Khách hàng vừa chốt mua căn hộ/nhà phố trên Hưng Phát Land được kết nối nhận gói ưu đãi thiết kế nội thất.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('noithat', 2, '🏨 Cung ứng Nội thất cho Khách sạn & Trường học (qldh / K12)', 'Đấu thầu và cung cấp bàn ghế học đường, nội thất phòng khách sạn cho các đơn vị thành viên trên Hub.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `app_integrations` (`app_id`, `integration_order`, `title`, `description`) VALUES ('noithat', 3, '🏢 Liên thông Kế toán, Kho & Nhân sự (erp)', 'Đồng bộ toàn bộ chi phí công trình, mua sắm vật tư và công nợ nhà cung cấp về TechCorp ERP.') ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
