INSERT INTO `forum_posts` (`id`, `category`, `category_label`, `status`, `locked`, `pinned`, `title`, `content`, `member_deal`, `author_name`, `author_org`, `author_role_badge`, `author_verified_app`, `created_at_label`, `likes`, `views`) VALUES ('POST-101', 'rfq', '📢 Cần Mua / Tìm Đối tác Nội bộ (RFQ)', 'approved', 0, 1, '[Cần tìm đối tác tại Nha Trang] Tìm Trung tâm đào tạo Tiếng Anh & Tiếng Hàn giao tiếp cho 25 nhân sự Lễ tân - Nhà hàng', 'Chào các anh/chị trong Cộng đồng TechCorp Khánh Hòa. Chuẩn bị đón đoàn khách quốc tế mùa cao điểm cuối năm, Nha Trang Bay Resort cần tìm 01 Trung tâm Ngoại ngữ uy tín trong hệ sinh thái để đào tạo cấp tốc 8 tuần (học kết hợp trên LMS Thi Online của TechCorp và thực hành tại khách sạn). Ưu tiên các trung tâm đang dùng hệ thống TechCorp để đồng bộ điểm chuyên cần trực tiếp về phân hệ HRM của chúng tôi.', 'Ký hợp đồng đào tạo dài hạn 12 tháng + Tài trợ địa điểm tổ chức sự kiện cho Trung tâm tại Resort.', 'CEO Khách sạn & Lữ hành Biển Nha Trang', 'Nha Trang Bay Resort & Travel', 'Khối Doanh nghiệp SME', 'Đang dùng: ERP + Website TechCorp', '30 phút trước', 18, 142) ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `category_label`=VALUES(`category_label`), `status`=VALUES(`status`), `locked`=VALUES(`locked`), `pinned`=VALUES(`pinned`), `title`=VALUES(`title`), `content`=VALUES(`content`), `member_deal`=VALUES(`member_deal`), `likes`=VALUES(`likes`), `views`=VALUES(`views`);
INSERT INTO `forum_comments` (`id`, `post_id`, `author_name`, `author_org`, `role_badge`, `comment_text`, `time_label`) VALUES ('CMT-1', 'POST-101', 'Giám đốc Trung tâm Anh ngữ & Tin học Quốc tế', 'Ocean English & IT Center Nha Trang', 'Khối Đào tạo NN-TH', 'Chào anh! Bên em có sẵn khung chương trình Tiếng Anh & Hàn chuyên ngành Hospitality trên LMS TechCorp, giảm ngay 25% học phí cho doanh nghiệp cùng hệ sinh thái. Em vừa gửi báo giá qua Hub nhé ạ!', '15 phút trước') ON DUPLICATE KEY UPDATE `comment_text`=VALUES(`comment_text`), `time_label`=VALUES(`time_label`);
INSERT INTO `forum_comments` (`id`, `post_id`, `author_name`, `author_org`, `role_badge`, `comment_text`, `time_label`) VALUES ('CMT-2', 'POST-101', 'Trung tâm Ngoại ngữ Á Châu (Vĩnh Điềm Trung)', 'Á Châu Language Center', 'Khối Đào tạo NN-TH', 'Bên mình có đội ngũ giáo viên bản xứ Hàn Quốc chuyên đào tạo cho các resort Bãi Dài - Cam Ranh và Trần Phú. Rất mong được kết nối hợp tác!', '8 phút trước') ON DUPLICATE KEY UPDATE `comment_text`=VALUES(`comment_text`), `time_label`=VALUES(`time_label`);
INSERT INTO `forum_posts` (`id`, `category`, `category_label`, `status`, `locked`, `pinned`, `title`, `content`, `member_deal`, `author_name`, `author_org`, `author_role_badge`, `author_verified_app`, `created_at_label`, `likes`, `views`) VALUES ('POST-102', 'spotlight', '🎁 Quảng bá & Đặc quyền Thành viên (Give-to-Get)', 'approved', 0, 1, '[Tài trợ Học bổng & Kiểm tra Năng lực] Tặng 500 suất Thi thử IELTS/TOEIC & Tin học Quốc tế + Học bổng 40% cho con em Doanh nghiệp & Trường học', 'Nhằm đồng hành cùng các Trường Mầm non - Phổ thông và gia đình cán bộ nhân viên các Doanh nghiệp SME tại Nha Trang, Ocean English & IT Center mở cổng kiểm tra năng lực Ngoại ngữ - Tin học định kỳ hoàn toàn miễn phí trên nền tảng Thi Online TechCorp. Toàn bộ kết quả được trả tự động về Sổ liên lạc điện tử của Phụ huynh.', '🎁 Đặc quyền bắt buộc (Give-to-Get): Giảm 40% học phí khóa đầu tiên + Tặng tài khoản luyện đề Online 6 tháng cho toàn bộ thành viên có TechCorp ID.', 'Giám đốc Trung tâm Anh ngữ & Tin học Quốc tế', 'Ocean English & IT Center Nha Trang', 'Khối Đào tạo NN-TH', 'Đang dùng: QL Trung tâm + Thi Online', '2 giờ trước', 34, 289) ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `category_label`=VALUES(`category_label`), `status`=VALUES(`status`), `locked`=VALUES(`locked`), `pinned`=VALUES(`pinned`), `title`=VALUES(`title`), `content`=VALUES(`content`), `member_deal`=VALUES(`member_deal`), `likes`=VALUES(`likes`), `views`=VALUES(`views`);
INSERT INTO `forum_comments` (`id`, `post_id`, `author_name`, `author_org`, `role_badge`, `comment_text`, `time_label`) VALUES ('CMT-3', 'POST-102', 'Ban Giám hiệu Trường CĐ / Mầm non Nha Trang', 'Hệ thống Giáo dục Sao Biển Nha Trang', 'Khối Cơ sở Giáo dục', 'Chương trình rất thiết thực! Trường Sao Biển đăng ký 120 suất kiểm tra tiếng Anh năng khiếu cuối tuần này cho các bé khối Lá và Tiểu học nhé.', '1 giờ trước') ON DUPLICATE KEY UPDATE `comment_text`=VALUES(`comment_text`), `time_label`=VALUES(`time_label`);
INSERT INTO `forum_posts` (`id`, `category`, `category_label`, `status`, `locked`, `pinned`, `title`, `content`, `member_deal`, `author_name`, `author_org`, `author_role_badge`, `author_verified_app`, `created_at_label`, `likes`, `views`) VALUES ('POST-1792469740466', 'rfq', '📢 Cần Mua / Tìm Đối tác Nội bộ (RFQ)', 'approved', 0, 0, '[Cam Ranh - Nha Trang] Cần đơn vị thiết kế Website đa ngôn ngữ & cung cấp đồng phục cho 40 nhân sự', 'Chúng tôi vừa mở thêm chi nhánh dịch vụ du lịch & lưu trú tại Bãi Dài - Cam Ranh, cần tìm đối tác trong Hệ sinh thái TechCorp thiết kế Website đa ngôn ngữ (Việt - Anh - Hàn - Nga) tích hợp đặt phòng trực tuyến và đơn vị may đồng phục khách sạn cao cấp cho 40 nhân sự mới.', 'Tặng 10 Voucher nghỉ dưỡng cuối tuần tại Resort cho đối tác ký hợp đồng triển khai trong tháng này.', 'Nguyễn Hải Đăng (CEO Resort & Travel)', 'Nha Trang Bay Resort & Travel', 'Khối Doanh nghiệp SME', 'Đang dùng: ERP + Website TechCorp', '2 giờ trước', 19, 164) ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `category_label`=VALUES(`category_label`), `status`=VALUES(`status`), `locked`=VALUES(`locked`), `pinned`=VALUES(`pinned`), `title`=VALUES(`title`), `content`=VALUES(`content`), `member_deal`=VALUES(`member_deal`), `likes`=VALUES(`likes`), `views`=VALUES(`views`);
INSERT INTO `forum_comments` (`id`, `post_id`, `author_name`, `author_org`, `role_badge`, `comment_text`, `time_label`) VALUES ('CMT-1792', 'POST-1792469740466', 'Ông Vũ Đình Khôi (Giám đốc Điều hành)', 'Công ty CP Thương mại & Dịch vụ SeaTech Khánh Hòa', 'Khối Doanh nghiệp SME', 'Bên SeaTech có bộ phận cung ứng đồng phục khách sạn chống nhăn cao cấp tại Nha Trang, giảm 15% cho thành viên Hệ sinh thái TechCorp. Em đã gửi mẫu vải qua Zalo nhé anh!', '1 giờ trước') ON DUPLICATE KEY UPDATE `comment_text`=VALUES(`comment_text`), `time_label`=VALUES(`time_label`);
INSERT INTO `forum_posts` (`id`, `category`, `category_label`, `status`, `locked`, `pinned`, `title`, `content`, `member_deal`, `author_name`, `author_org`, `author_role_badge`, `author_verified_app`, `created_at_label`, `likes`, `views`) VALUES ('POST-103', 'comarketing', '🤝 Hợp tác Chéo & Đồng tổ chức Sự kiện', 'approved', 0, 0, 'Mời 05 Doanh nghiệp Du lịch / F&B / Nha khoa tại Nha Trang đồng hành Ngày hội Gia đình & Tuyển sinh Mùa Hè (Quy mô 800 Phụ huynh)', 'Tháng tới Hệ thống Giáo dục Sao Biển (KĐT Mỹ Gia & Vĩnh Điềm Trung) tổ chức Ngày hội Trải nghiệm Công nghệ & Kỹ năng cho 800 phụ huynh học sinh. Nhà trường dành tặng 05 gian hàng trưng bày miễn phí và tích hợp phát E-Voucher trên App Sổ liên lạc Điện tử cho các doanh nghiệp cùng thuộc Hệ sinh thái TechCorp.', 'Miễn phí 100% gian hàng + Đẩy thông báo thương hiệu tài trợ tới 1.200 Phụ huynh trên App Trường.', 'Ban Giám hiệu Trường CĐ / Mầm non Nha Trang', 'Hệ thống Giáo dục Sao Biển Nha Trang', 'Khối Cơ sở Giáo dục', 'Đang dùng: QL Trường học + LMS', '5 giờ trước', 27, 195) ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `category_label`=VALUES(`category_label`), `status`=VALUES(`status`), `locked`=VALUES(`locked`), `pinned`=VALUES(`pinned`), `title`=VALUES(`title`), `content`=VALUES(`content`), `member_deal`=VALUES(`member_deal`), `likes`=VALUES(`likes`), `views`=VALUES(`views`);
INSERT INTO `forum_posts` (`id`, `category`, `category_label`, `status`, `locked`, `pinned`, `title`, `content`, `member_deal`, `author_name`, `author_org`, `author_role_badge`, `author_verified_app`, `created_at_label`, `likes`, `views`) VALUES ('POST-104', 'knowledge', '💡 Góc Chia sẻ Quản trị, HR & Chuyển đổi số', 'approved', 0, 0, 'Kinh nghiệm tự động hóa 95% quy trình thu học phí QR & chấm công giáo viên tại Nha Trang bằng hệ sinh thái TechCorp', 'Trước đây mỗi đầu tháng bộ phận kế toán của trường mất gần 5 ngày để đối soát tin nhắn chuyển khoản học phí của phụ huynh. Từ khi bật tính năng gạch nợ tự động qua QR động trên phần mềm Quản lý Trường học và đồng bộ sang phân hệ Tài chính ERP của TechCorp, phụ huynh quét mã 3 giây là biên lai điện tử xuất tự động, kế toán giảm được 80% khối lượng việc thủ công.', 'Chia sẻ miễn phí bộ quy trình & biểu mẫu thiết lập thu học phí không tiền mặt cho các trường tại Khánh Hòa.', 'Ban Giám hiệu Trường CĐ / Mầm non Nha Trang', 'Hệ thống Giáo dục Sao Biển Nha Trang', 'Khối Cơ sở Giáo dục', 'Đang dùng: QL Trường học + LMS', '1 ngày trước', 41, 310) ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `category_label`=VALUES(`category_label`), `status`=VALUES(`status`), `locked`=VALUES(`locked`), `pinned`=VALUES(`pinned`), `title`=VALUES(`title`), `content`=VALUES(`content`), `member_deal`=VALUES(`member_deal`), `likes`=VALUES(`likes`), `views`=VALUES(`views`);
INSERT INTO `forum_posts` (`id`, `category`, `category_label`, `status`, `locked`, `pinned`, `title`, `content`, `member_deal`, `author_name`, `author_org`, `author_role_badge`, `author_verified_app`, `created_at_label`, `likes`, `views`) VALUES ('POST-105', 'rfq', '📢 Cần Mua / Tìm Đối tác Nội bộ (RFQ)', 'approved', 0, 0, '[Bãi Dài - Cam Ranh] Tìm nhà cung ứng thực phẩm sạch VietGAP hàng ngày & tiếp nhận 15 Sinh viên Thực tập Quản trị Khách sạn', 'Asia Bay Resort & Spa Cam Ranh (quy mô 220 phòng & biệt thự biển) đang mở rộng công suất đón đoàn khách MICE quốc tế. Chúng tôi cần kết nối với đơn vị cung ứng thực phẩm - rau củ - hải sản đạt chuẩn VietGAP tại Khánh Hòa và tiếp nhận 15 sinh viên năm cuối ngành Du lịch - Nhà hàng thực tập có hưởng phụ cấp.', 'Thanh toán công nợ tự động 7 ngày/lần qua TechCorp ERP + Tài trợ gói Teambuilding bãi biển giảm 35% cho đối tác.', 'Ông Trần Quốc Bảo (Tổng Quản lý GM)', 'Asia Bay Resort & Spa Cam Ranh', 'Khối Doanh nghiệp SME', 'Đang dùng: TechCorp PMS + ERP', '4 giờ trước', 23, 178) ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `category_label`=VALUES(`category_label`), `status`=VALUES(`status`), `locked`=VALUES(`locked`), `pinned`=VALUES(`pinned`), `title`=VALUES(`title`), `content`=VALUES(`content`), `member_deal`=VALUES(`member_deal`), `likes`=VALUES(`likes`), `views`=VALUES(`views`);
INSERT INTO `forum_comments` (`id`, `post_id`, `author_name`, `author_org`, `role_badge`, `comment_text`, `time_label`) VALUES ('CMT-105-1', 'POST-105', 'Bà Nguyễn Thị Thu Thủy (Giám đốc Điều hành)', 'Công ty CP Thực phẩm & Suất ăn Học đường Biển Xanh Nha Trang', 'Khối Doanh nghiệp SME', 'Thực phẩm Biển Xanh hiện có xe lạnh giao tuyến Nha Trang - Bãi Dài Cam Ranh lúc 5h30 sáng hàng ngày, đầy đủ chứng nhận VietGAP & ISO 22000. Rất mong được hợp tác cùng Asia Bay Resort!', '2 giờ trước') ON DUPLICATE KEY UPDATE `comment_text`=VALUES(`comment_text`), `time_label`=VALUES(`time_label`);
INSERT INTO `forum_posts` (`id`, `category`, `category_label`, `status`, `locked`, `pinned`, `title`, `content`, `member_deal`, `author_name`, `author_org`, `author_role_badge`, `author_verified_app`, `created_at_label`, `likes`, `views`) VALUES ('POST-106', 'spotlight', '🎁 Quảng bá & Đặc quyền Thành viên (Give-to-Get)', 'approved', 0, 0, '[Đặc quyền Học đường] Giảm 12% hợp đồng suất ăn bán trú chuẩn VietGAP & đồng bộ thực đơn dinh dưỡng lên Sổ liên lạc EduManager', 'Nhà máy chế biến suất ăn học đường Biển Xanh (KCN Đắc Lộc - Nha Trang) đạt chuẩn ISO 22000 & VietGAP hiện đang cung cấp 6.500 suất ăn/ngày. Chúng tôi tích hợp API đồng bộ thực đơn hàng ngày, hình ảnh mẫu thức ăn lưu nghiệm và định lượng Kcal trực tiếp lên Sổ liên lạc điện tử EduManager Pro để phụ huynh theo dõi minh bạch.', '🎁 Giảm ngay 12% giá trị hợp đồng năm học mới + Tài trợ 100% tủ giữ nhiệt inox công nghiệp tại bếp ăn nhà trường.', 'Bà Nguyễn Thị Thu Thủy (Giám đốc Điều hành)', 'Công ty CP Thực phẩm & Suất ăn Học đường Biển Xanh Nha Trang', 'Khối Doanh nghiệp SME', 'Đang dùng: ERP Kho vận + Website TechCorp', '5 giờ trước', 31, 215) ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `category_label`=VALUES(`category_label`), `status`=VALUES(`status`), `locked`=VALUES(`locked`), `pinned`=VALUES(`pinned`), `title`=VALUES(`title`), `content`=VALUES(`content`), `member_deal`=VALUES(`member_deal`), `likes`=VALUES(`likes`), `views`=VALUES(`views`);
INSERT INTO `forum_posts` (`id`, `category`, `category_label`, `status`, `locked`, `pinned`, `title`, `content`, `member_deal`, `author_name`, `author_org`, `author_role_badge`, `author_verified_app`, `created_at_label`, `likes`, `views`) VALUES ('POST-107', 'spotlight', '🎁 Quảng bá & Đặc quyền Thành viên (Give-to-Get)', 'approved', 0, 0, '[Ưu đãi Mở rộng Cơ sở] Giảm 20% gói Thiết kế - Thi công Phòng học Thông minh & Văn phòng Doanh nghiệp tại Nha Trang', 'Liên minh Sàn Giao dịch BĐS Hưng Phát Land & Xưởng Nội thất TechCorp 3D cung cấp dịch vụ trọn gói từ tìm kiếm mặt bằng mở trường/trung tâm tại KĐT Mỹ Gia, Hà Quang II, Vĩnh Điềm Trung đến thiết kế 3D và thi công nội thất phòng học chuẩn quốc tế, văn phòng làm việc hiện đại.', '🎁 Miễn phí 100% bản vẽ thiết kế 3D phối cảnh + Chiết khấu 20% giá xuất xưởng nội thất cho đơn vị thành viên TechCorp.', 'Ban Giám đốc Hưng Phát Land', 'Sàn Giao dịch BĐS Hưng Phát Land & Nội thất 3D', 'Khối Bất động sản & Nội thất', 'Đang dùng: BĐS AI + Nội thất 3D', '6 giờ trước', 29, 240) ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `category_label`=VALUES(`category_label`), `status`=VALUES(`status`), `locked`=VALUES(`locked`), `pinned`=VALUES(`pinned`), `title`=VALUES(`title`), `content`=VALUES(`content`), `member_deal`=VALUES(`member_deal`), `likes`=VALUES(`likes`), `views`=VALUES(`views`);
INSERT INTO `forum_posts` (`id`, `category`, `category_label`, `status`, `locked`, `pinned`, `title`, `content`, `member_deal`, `author_name`, `author_org`, `author_role_badge`, `author_verified_app`, `created_at_label`, `likes`, `views`) VALUES ('POST-108', 'comarketing', '🤝 Hợp tác Chéo & Đồng tổ chức Sự kiện', 'approved', 0, 0, '[Job Fair & Thực tập Doanh nghiệp] Mời 30 Doanh nghiệp SME & Resort tham gia Tuần lễ Tuyển dụng & Phỏng vấn Thực tập sinh Số', 'Phối hợp cùng Sàn Tuyển dụng AI (jobai.techcorp.info.vn), Trung tâm Hợp tác Doanh nghiệp tổ chức đợt kết nối 450 sinh viên năm cuối các ngành CNTT, Quản trị Khách sạn, Kế toán, Ngôn ngữ Anh - Hàn - Trung đã có Hồ sơ Năng lực Số xác thực điểm thi LMS với các doanh nghiệp trong Hệ sinh thái TechCorp.', 'Miễn phí bàn phỏng vấn trực tiếp tại Hội trường + Cấp quyền truy cập sớm 450 CV xác thực trên Sàn JobAI.', 'Ban Hợp tác Doanh nghiệp & Việc làm Sinh viên', 'Trường Đại học Nha Trang (NTU)', 'Khối Cơ sở Giáo dục', 'Đang dùng: TC COMPASS + JobAI', '8 giờ trước', 45, 360) ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `category_label`=VALUES(`category_label`), `status`=VALUES(`status`), `locked`=VALUES(`locked`), `pinned`=VALUES(`pinned`), `title`=VALUES(`title`), `content`=VALUES(`content`), `member_deal`=VALUES(`member_deal`), `likes`=VALUES(`likes`), `views`=VALUES(`views`);
INSERT INTO `forum_posts` (`id`, `category`, `category_label`, `status`, `locked`, `pinned`, `title`, `content`, `member_deal`, `author_name`, `author_org`, `author_role_badge`, `author_verified_app`, `created_at_label`, `likes`, `views`) VALUES ('POST-109', 'spotlight', '🎁 Quảng bá & Đặc quyền Thành viên (Give-to-Get)', 'approved', 0, 0, '[Đào tạo Ngoại ngữ Doanh nghiệp] Tặng gói đào tạo Tiếng Hàn - Nhật - Trung chuyên ngành Du lịch & F&B giảm 30% học phí', 'Đáp ứng làn sóng du khách Hàn Quốc, Nhật Bản và Trung Quốc tăng mạnh tại Nha Trang - Khánh Hòa, Trung tâm Ngoại ngữ Á Châu thiết kế các khóa giao tiếp thực chiến 6 tuần dành riêng cho nhân viên Lễ tân, Buồng phòng, Nhà hàng, Spa với lịch học linh hoạt theo ca.', '🎁 Giảm 30% học phí cho doanh nghiệp đăng ký từ 10 nhân sự + Miễn phí kiểm tra đầu vào và cấp chứng chỉ số trên TechCorp LMS.', 'Ban Giám đốc Trung tâm Ngoại ngữ Á Châu', 'Á Châu Language Center', 'Khối Đào tạo NN-TH', 'Đang dùng: QL Trung tâm + LMS', '12 giờ trước', 22, 185) ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `category_label`=VALUES(`category_label`), `status`=VALUES(`status`), `locked`=VALUES(`locked`), `pinned`=VALUES(`pinned`), `title`=VALUES(`title`), `content`=VALUES(`content`), `member_deal`=VALUES(`member_deal`), `likes`=VALUES(`likes`), `views`=VALUES(`views`);
INSERT INTO `forum_posts` (`id`, `category`, `category_label`, `status`, `locked`, `pinned`, `title`, `content`, `member_deal`, `author_name`, `author_org`, `author_role_badge`, `author_verified_app`, `created_at_label`, `likes`, `views`) VALUES ('POST-110', 'knowledge', '💡 Góc Chia sẻ Quản trị, HR & Chuyển đổi số', 'approved', 0, 0, '[Case Study Thực tế] Cách SeaTech Khánh Hòa áp dụng Thẻ điểm cân bằng BSC-KPI & ERP giúp tăng 38% năng suất đội ngũ kinh doanh', 'Sau 3 tháng chuyển đổi từ bảng tính Excel rời rạc sang bộ đôi TechCorp ERP và Quản trị Mục tiêu BSC-KPI (kpi.techcorp.info.vn), toàn bộ 85 nhân sự của SeaTech đã nắm rõ mục tiêu OKR/KPI theo tuần. Hệ thống tự động tính hoa hồng và thưởng hiệu suất minh bạch, giảm 90% tranh chấp cuối kỳ.', 'Chia sẻ miễn phí bộ thư viện 45 chỉ số KPI mẫu cho bộ phận Sales, Marketing, Nhân sự & Kế toán doanh nghiệp SME.', 'Ông Vũ Đình Khôi (Giám đốc Điều hành)', 'Công ty CP Thương mại & Dịch vụ SeaTech Khánh Hòa', 'Khối Doanh nghiệp SME', 'Đang dùng: TechCorp ERP + BSC-KPI', '1 ngày trước', 36, 274) ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `category_label`=VALUES(`category_label`), `status`=VALUES(`status`), `locked`=VALUES(`locked`), `pinned`=VALUES(`pinned`), `title`=VALUES(`title`), `content`=VALUES(`content`), `member_deal`=VALUES(`member_deal`), `likes`=VALUES(`likes`), `views`=VALUES(`views`);
INSERT INTO `forum_posts` (`id`, `category`, `category_label`, `status`, `locked`, `pinned`, `title`, `content`, `member_deal`, `author_name`, `author_org`, `author_role_badge`, `author_verified_app`, `created_at_label`, `likes`, `views`) VALUES ('POST-111', 'comarketing', '🤝 Hợp tác Chéo & Đồng tổ chức Sự kiện', 'approved', 0, 0, '[Hợp tác CLB Tiếng Anh Học đường] Tài trợ Giáo viên Bản xứ giao lưu Ngoại khóa cuối tuần cho các Trường Tiểu học & THCS', 'Hệ thống Anh ngữ Quốc tế Global Star (3 cơ sở tại Nha Trang) triển khai chương trình \'English STEM & Robotics Weekend\' dành cho các trường Tiểu học và THCS. Đội ngũ giáo viên bản xứ của Global Star sẽ trực tiếp về trường đồng tổ chức CLB tiếng Anh hoàn toàn miễn phí.', 'Tài trợ 100% chi phí giáo viên bản xứ + Tặng 50 học bổng bán phần khóa hè cho học sinh xuất sắc của trường.', 'Bà Phạm Hoàng Yến (Giám đốc Học vụ)', 'Hệ thống Anh ngữ Quốc tế Global Star', 'Khối Đào tạo NN-TH', 'Đang dùng: QL Trung tâm + TechCorpLearn', '2 ngày trước', 25, 208) ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `category_label`=VALUES(`category_label`), `status`=VALUES(`status`), `locked`=VALUES(`locked`), `pinned`=VALUES(`pinned`), `title`=VALUES(`title`), `content`=VALUES(`content`), `member_deal`=VALUES(`member_deal`), `likes`=VALUES(`likes`), `views`=VALUES(`views`);
INSERT INTO `forum_posts` (`id`, `category`, `category_label`, `status`, `locked`, `pinned`, `title`, `content`, `member_deal`, `author_name`, `author_org`, `author_role_badge`, `author_verified_app`, `created_at_label`, `likes`, `views`) VALUES ('POST-112', 'spotlight', '🎁 Quảng bá & Đặc quyền Thành viên (Give-to-Get)', 'approved', 0, 0, '[Phúc lợi Y tế Học đường & Doanh nghiệp] Khám răng định kỳ miễn phí tại Trường học & Giảm 30% dịch vụ Nha khoa cho nhân sự TechCorp ID', 'Hệ thống Nha khoa & Phòng khám Quốc tế Sài Gòn - Nha Trang triển khai gói chăm sóc sức khỏe răng miệng lưu động tại các trường Mầm non, Tiểu học và tặng gói khám tổng quát miễn phí cho toàn bộ cán bộ nhân viên doanh nghiệp thuộc Hệ sinh thái TechCorp.', '🎁 Khám răng định kỳ miễn phí 100% tại trường học + Giảm 30% dịch vụ nha khoa thẩm mỹ cho chủ thẻ TechCorp ID.', 'BS. CKII Nguyễn Trọng Nghĩa (Giám đốc Chuyên môn)', 'Hệ thống Nha khoa Quốc tế Sài Gòn - Nha Trang', 'Khối Doanh nghiệp SME', 'Đang dùng: CRM Chăm sóc khách hàng TechCorp', '2 ngày trước', 33, 256) ON DUPLICATE KEY UPDATE `category`=VALUES(`category`), `category_label`=VALUES(`category_label`), `status`=VALUES(`status`), `locked`=VALUES(`locked`), `pinned`=VALUES(`pinned`), `title`=VALUES(`title`), `content`=VALUES(`content`), `member_deal`=VALUES(`member_deal`), `likes`=VALUES(`likes`), `views`=VALUES(`views`);
INSERT INTO `announcements` (`id`, `source_type`, `badge`, `title`, `summary`, `author_name`, `author_org`, `created_at_label`, `pinned`, `action_label`, `action_view`) VALUES ('ANN-MASTER-01', 'master', '👑 THÔNG BÁO ĐIỀU HÀNH TỪ HỆ SINH THÁI TECHCORP', 'Chính thức Liên thông 16 Nền tảng Phần mềm Thực tế trên *.techcorp.info.vn qua Trục SSO TechCorp ID v5.1', 'Toàn bộ 16 hệ thống đang chạy thực tế gồm: Giáo dục K12 (mamnon, tieuhoc, thcs, thpt, gdtx), Đại học & Khảo thí (qldt TC COMPASS, ttnn, lms, learn), Tuyển dụng AI (jobai), Quản trị Doanh nghiệp (erp, kpi, techcorp) và Chuyên ngành (qldh PMS Khách sạn, bds AI, noithat) đã được kết nối tập trung.', 'Ban Điều hành Hệ sinh thái TechCorp', 'TechCorp Headquarters (Nha Trang - Khánh Hòa)', 'Hôm nay, 08:00', 1, 'Xem 6 Nhóm Sản phẩm', 'pub-page-products') ON DUPLICATE KEY UPDATE `badge`=VALUES(`badge`), `title`=VALUES(`title`), `summary`=VALUES(`summary`), `pinned`=VALUES(`pinned`);
